import { useEffect as useReactEffect, useMemo, useRef, useState } from 'react';
import { createPortal } from 'react-dom';
import { Link, useNavigate, useParams, useSearchParams } from 'react-router-dom';
import { Activity, ArrowLeft, BarChart3, Building2, CalendarDays, CheckCircle2, ChevronDown, CircleDollarSign, Clock3, Download, Edit3, Eye, Filter, GripVertical, LayoutGrid, List, Mail, MoreHorizontal, MoreVertical, Plus, RotateCcw, Search, Star, Trash2, Upload, UserRound, Users, XCircle } from 'lucide-react';
import { companyApi, contactApi, leadApi, pipelineApi, supportApi } from '../../api/leadManagementApi.js';
import { ConfirmDialog } from '../../components/ConfirmDialog.jsx';
import { MessageDialog } from '../../components/MessageDialog.jsx';
import { useAuthStore } from '../../store/authStore.js';

const money = (v) => new Intl.NumberFormat('en-IN', { style: 'currency', currency: 'INR', maximumFractionDigits: 0 }).format(Number(v || 0));
const date = (v) => v ? new Date(v).toLocaleDateString('en-IN', { day: '2-digit', month: 'short', year: 'numeric' }) : '—';
const currentFinancialYear = () => { const now = new Date(); const year = now.getMonth() >= 3 ? now.getFullYear() : now.getFullYear() - 1; return { from: `${year}-04-01`, to: `${year + 1}-03-31` }; };
const card = 'lead-card rounded-[10px] border border-slate-200 bg-white';
const field = 'lead-field h-10 w-full rounded-md border border-slate-200 bg-white px-3 text-[13px] outline-none transition focus:border-red-400 focus:ring-2 focus:ring-red-100';
const btn = 'lead-button inline-flex h-10 items-center justify-center gap-2 rounded-md border border-slate-200 bg-white px-4 text-[13px] font-bold text-slate-800 transition hover:border-slate-300 hover:bg-slate-50';
const primary = `${btn} border-red-600 bg-red-600 text-white hover:bg-red-700`;

// Keep React's effect contract explicit for this module. Form hydration effects
// perform state updates only; async data effects return their real cancellation
// callback. A conditional expression must never leak null/false as a cleanup.
function useEffect(effect, dependencies) {
  useReactEffect(() => {
    const cleanup = effect();
    return typeof cleanup === 'function' ? cleanup : undefined;
  }, dependencies);
}

function useLoad(loader, deps = []) {
  const [state, setState] = useState({ data: null, loading: true, error: '' });
  useEffect(() => { let live = true; setState((s) => ({ ...s, loading: true, error: '' })); loader().then((data) => live && setState({ data, loading: false, error: '' })).catch((e) => live && setState({ data: null, loading: false, error: e.response?.data?.message || e.message })); return () => { live = false; }; }, deps);
  return state;
}

function Page({ title, subtitle, actions, children }) { return <div className="lead-module space-y-4"><div className="lead-page-header flex flex-wrap items-center justify-between gap-3"><div><h1 className="text-[22px] font-extrabold tracking-[-.02em] text-[#07152b]">{title}</h1><p className="mt-1 text-[13px] text-slate-600">{subtitle}</p></div><div className="lead-page-actions flex flex-wrap items-center gap-2">{actions}</div></div>{children}</div>; }
function Loading({ error }) { return <div className={`${card} grid min-h-40 place-items-center p-8 text-sm font-semibold text-slate-500`}>{error || 'Loading…'}</div>; }
function Badge({ children, tone = 'blue' }) { const colors = { red: 'bg-red-50 text-red-600', green: 'bg-emerald-50 text-emerald-700', blue: 'bg-blue-50 text-blue-700', amber: 'bg-amber-50 text-amber-700', slate: 'bg-slate-100 text-slate-700', violet: 'bg-violet-50 text-violet-700' }; return <span className={`inline-flex rounded px-2 py-1 text-xs font-bold ${colors[tone]}`}>{children || '—'}</span>; }
function tone(value) { const v = String(value || '').toUpperCase(); return v.includes('LOST') || v.includes('INACTIVE') ? 'red' : v.includes('WON') || v.includes('CONVERTED') || v.includes('QUALIFIED') || v.includes('ACTIVE') ? 'green' : v.includes('NEW') ? 'slate' : v.includes('NEGOT') ? 'amber' : 'blue'; }
function Stats({ items }) { const tones=['red','blue','amber','green','rose']; return <div className="lead-stats grid gap-3 sm:grid-cols-2 xl:grid-cols-5">{items.map(({ label, value, icon: Icon = BarChart3, hint },index) => <div key={label} className={`${card} lead-stat flex min-h-[106px] items-center gap-4 p-4`}><span className={`lead-stat-icon lead-stat-icon--${tones[index%tones.length]} grid h-12 w-12 shrink-0 place-items-center rounded-full`}><Icon className="h-6 w-6" /></span><div className="min-w-0"><p className="text-[12px] font-bold text-slate-600">{label}</p><p className="mt-1 text-[24px] font-extrabold leading-none text-[#07152b]">{value ?? 0}</p>{hint && <p className="mt-2 truncate text-[11px] text-slate-500">{hint}</p>}</div></div>)}</div>; }
function Empty({ text = 'No records found.' }) { return <div className="py-14 text-center text-sm font-semibold text-slate-400">{text}</div>; }
function Pager({ page, totalPages, onChange }) { const pages=Math.max(totalPages||1,1); return <div className="lead-pager flex items-center justify-between border-t border-slate-100 px-4 py-3 text-xs text-slate-500"><span>Showing page {page+1} of {pages}</span><div className="flex items-center gap-2"><button aria-label="Previous page" className="grid h-9 w-9 place-items-center rounded-md border border-slate-200 bg-white disabled:opacity-40" disabled={!page} onClick={()=>onChange(page-1)}>‹</button><span className="grid h-9 min-w-9 place-items-center rounded-md border border-red-400 bg-red-50 px-2 font-bold text-red-600">{page+1}</span><button aria-label="Next page" className="grid h-9 w-9 place-items-center rounded-md border border-slate-200 bg-white disabled:opacity-40" disabled={page+1>=pages} onClick={()=>onChange(page+1)}>›</button><span className="ml-2 rounded-md border border-slate-200 px-3 py-2">10 / page</span></div></div>; }
function RowMenu({ viewTo, editTo, onAssign, onDelete }) {
  const [open,setOpen]=useState(false);
  const trigger=useRef(null);
  const rect=trigger.current?.getBoundingClientRect();
  return <div className="relative"><button ref={trigger} aria-label="Record actions" className="grid h-8 w-8 place-items-center rounded-md hover:bg-slate-100" onClick={()=>setOpen(value=>!value)}><MoreVertical className="h-4 w-4"/></button>{open&&createPortal(<><button aria-label="Close actions" className="fixed inset-0 z-[90] cursor-default" onClick={()=>setOpen(false)}/><div className="fixed z-[100] w-40 rounded-lg border border-slate-200 bg-white p-1 shadow-2xl" style={{top:Math.min((rect?.bottom||0)+6,window.innerHeight-170),left:Math.max(8,(rect?.right||160)-160)}}><Link className="flex items-center gap-2 rounded-md px-3 py-2 text-xs font-bold hover:bg-slate-50" to={viewTo} onClick={()=>setOpen(false)}><Eye className="h-4 w-4"/>View</Link><Link className="flex items-center gap-2 rounded-md px-3 py-2 text-xs font-bold hover:bg-slate-50" to={editTo} onClick={()=>setOpen(false)}><Edit3 className="h-4 w-4"/>Edit</Link>{onAssign&&<button className="flex w-full items-center gap-2 rounded-md px-3 py-2 text-left text-xs font-bold hover:bg-slate-50" onClick={()=>{setOpen(false);onAssign();}}><UserRound className="h-4 w-4"/>Assign</button>}<button className="flex w-full items-center gap-2 rounded-md px-3 py-2 text-left text-xs font-bold text-red-600 hover:bg-red-50" onClick={()=>{setOpen(false);onDelete();}}><Trash2 className="h-4 w-4"/>Delete</button></div></>,document.body)}</div>;
}

function AssignLeadModal({ lead, onClose, onSaved }) {
  const { data: assignees, loading, error: loadError } = useLoad(leadApi.eligibleAssignees, []);
  const employeeOptions = Array.isArray(assignees) ? assignees : (assignees?.content || assignees?.data || []);
  const [employeeId,setEmployeeId]=useState('');
  const [note,setNote]=useState('');
  const [saving,setSaving]=useState(false);
  const [error,setError]=useState('');
  const submit=async()=>{if(!employeeId){setError('Please select an employee.');return;}setSaving(true);setError('');try{await leadApi.assign(lead.id,{employeeId:Number(employeeId),note:note.trim()||null});onSaved();}catch(caught){setSaving(false);setError(caught.response?.data?.message||caught.message||'Lead assignment failed.');}};
  return createPortal(<div className="fixed inset-0 z-[120] grid place-items-center bg-[#06134a]/60 p-4"><div className="w-full max-w-lg overflow-hidden rounded-xl border border-slate-200 bg-white shadow-2xl"><div className="flex items-center justify-between border-b px-5 py-4"><div><h2 className="text-lg font-black text-[#07152b]">Assign Lead</h2><p className="mt-1 text-xs text-slate-500">{lead.leadName}</p></div><button className="grid h-9 w-9 place-items-center rounded-lg hover:bg-slate-50" onClick={onClose}>×</button></div><div className="space-y-4 p-5">{(error||loadError)&&<div className="rounded-md border border-red-200 bg-red-50 p-3 text-xs font-bold text-red-700">{error||loadError}</div>}<label className="block text-xs font-bold">Assign To *<select className={`${field} mt-2`} disabled={loading} value={employeeId} onChange={event=>setEmployeeId(event.target.value)}><option value="">{loading?'Loading employees…':employeeOptions.length?'Select employee':'No eligible Sales or Vendor employees found'}</option>{employeeOptions.map(employee=><option key={employee.employeeId} value={employee.employeeId}>{employee.name}</option>)}</select></label><label className="block text-xs font-bold">Note<textarea className={`${field} mt-2 h-28 py-3`} maxLength={1000} placeholder="Add assignment instructions (optional)" value={note} onChange={event=>setNote(event.target.value)}/></label></div><div className="flex justify-end gap-3 border-t px-5 py-4"><button className={btn} disabled={saving} onClick={onClose}>Cancel</button><button className="lead-button inline-flex h-10 min-w-[145px] items-center justify-center rounded-md border border-red-600 bg-red-600 px-5 text-[13px] font-bold text-white transition hover:bg-red-700 disabled:opacity-60" disabled={saving||loading||!employeeId} onClick={submit}><span>{saving?'Assigning…':'Assign Lead'}</span></button></div></div></div>,document.body);
}

function Bars({ data = [], color = '#ef1f2c' }) { const max = Math.max(1, ...data.map((x) => Number(x.value))); return <div className="flex h-52 items-end gap-3 border-b border-slate-200 px-3 pt-4">{data.length ? data.map((x) => <div key={x.label} className="flex min-w-0 flex-1 flex-col items-center gap-2"><span className="text-xs font-bold">{x.value}</span><div className="w-full max-w-16 rounded-t" style={{ height: `${Math.max(7, Number(x.value) / max * 145)}px`, background: color }} /><span className="w-full truncate text-center text-[10px] text-slate-500">{x.label || 'Unknown'}</span></div>) : <Empty />}</div>; }
function Donut({ data = [] }) { const colors = ['#ef1f2c', '#2563eb', '#10b981', '#f59e0b', '#8b5cf6', '#64748b']; const total = data.reduce((s, x) => s + Number(x.value), 0); let at = 0; const stops = data.map((x, i) => { const from = at; at += total ? Number(x.value) / total * 360 : 0; return `${colors[i % colors.length]} ${from}deg ${at}deg`; }); return <div className="flex min-h-52 items-center justify-center gap-7"><div className="grid h-36 w-36 place-items-center rounded-full" style={{ background: `conic-gradient(${stops.join(',') || '#e2e8f0 0deg 360deg'})` }}><div className="grid h-20 w-20 place-items-center rounded-full bg-white text-center"><b className="text-xl">{total}</b></div></div><div className="space-y-2">{data.slice(0, 6).map((x, i) => <div key={x.label} className="flex items-center gap-2 text-xs"><i className="h-2 w-2 rounded-full" style={{ background: colors[i % colors.length] }} /><span className="max-w-28 truncate">{x.label}</span><b>{x.value}</b></div>)}</div></div>; }
function ChartCard({ title, children }) { return <section className={`${card} lead-chart-card p-4`}><h2 className="text-[14px] font-extrabold text-[#07152b]">{title}</h2>{children}</section>; }

export function LeadDashboardPage() {
  const user=useAuthStore(state=>state.user);
  const [filters, setFilters] = useState(()=>({...currentFinancialYear(),owner:user?.role==='admin'?'':String(user?.id||'')})); const { data, loading, error } = useLoad(() => leadApi.dashboard(filters), [JSON.stringify(filters)]); const options = useLoad(leadApi.options, []).data;
  if (loading || !data) return <Loading error={error} />;
  const change = data.changes || {};
  const sourcePerformance=(data.bySource||[]).map((source)=>({ ...source, converted:Number(source.converted||0), rate:Number(source.value)?Number(source.converted||0)*100/Number(source.value):0 }));
  return <Page title="Lead Dashboard" subtitle="Track and manage your leads performance overview." actions={<><div className="flex items-center gap-2 rounded-md border border-slate-200 bg-white px-3"><CalendarDays className="h-4 w-4"/><input aria-label="Dashboard from date" className="h-10 bg-transparent text-xs outline-none" type="date" value={filters.from} onChange={(e)=>setFilters({...filters,from:e.target.value})}/><span className="text-slate-400">–</span><input aria-label="Dashboard to date" className="h-10 bg-transparent text-xs outline-none" type="date" value={filters.to} onChange={(e)=>setFilters({...filters,to:e.target.value})}/></div><select className={field} value={filters.pipelineId||''} onChange={(e) => setFilters({ ...filters, pipelineId: e.target.value })}><option value="">All Pipelines</option>{options?.pipelines?.map((p) => <option key={p.id} value={p.id}>{p.name}</option>)}</select><select aria-label="Dashboard employee" className={field} value={filters.owner||''} disabled={user?.role!=='admin'&&(options?.dashboardEmployees||[]).length<=1} onChange={(e)=>setFilters({...filters,owner:e.target.value})}>{user?.role==='admin'&&<option value="">All Employees</option>}{(options?.dashboardEmployees||[]).map(employee=><option key={employee.userId} value={employee.value}>{employee.name}</option>)}</select><button className={btn}><Filter className="h-4 w-4" /> Filters</button><button className={btn}>Customise</button></>}>
    <Stats items={[['Total Leads',data.totalLeads,Users],['New Leads',data.newLeads,UserRound],['Qualified Leads',data.qualifiedLeads,CheckCircle2],['Converted Leads',data.convertedLeads,CircleDollarSign],['Lost Leads',data.lostLeads,XCircle]].map(([label,value,icon]) => ({ label,value,icon,hint:`${change[label.replaceAll(' ','').replace(/^./,c=>c.toLowerCase())] || 0}% vs previous period` }))} />
    <div className="grid gap-4 xl:grid-cols-4"><ChartCard title="Leads by Pipeline"><Donut data={data.byPipeline} /></ChartCard><ChartCard title="Leads by Status"><Bars data={data.byStatus} color="#2563eb" /></ChartCard><ChartCard title="Leads Over Time"><Bars data={data.overTime} /></ChartCard><ChartCard title="Leads by Source"><Donut data={data.bySource} /></ChartCard></div>
    <div className="grid gap-4 xl:grid-cols-4"><ChartCard title="Employee Wise Leads"><Bars data={data.byOwner} /></ChartCard><ChartCard title="Leads by Type"><Donut data={data.byType} /></ChartCard><ChartCard title="Leads by Owner"><Donut data={data.byOwner} /></ChartCard><ChartCard title="Lead Conversion Rate"><div className="grid min-h-52 place-items-center"><div className="text-center"><div className="mx-auto h-24 w-48 overflow-hidden rounded-t-full bg-slate-200"><div className="h-full origin-bottom-left bg-emerald-500" style={{clipPath:`polygon(0 100%, ${Math.min(100,Number(data.conversionRate||0))}% 0, 100% 100%)`}}/></div><b className="mt-3 block text-3xl">{Number(data.conversionRate||0).toFixed(2)}%</b><span className="text-xs text-emerald-600">Lead conversion rate</span></div></div></ChartCard></div>
    <div className="grid gap-4 xl:grid-cols-[280px_1.4fr_1fr]"><ChartCard title="Key Metrics"><div className="mt-5 space-y-4">{[['Average Lead Age',`${Math.round(data.averageLeadAge || 0)} days`],['Pipeline Weighted Value',money(data.weightedValue)],['Won Leads Revenue',money(data.wonRevenue)],['Conversion Rate',`${data.conversionRate || 0}%`]].map(([k,v]) => <div className="flex justify-between border-b pb-3 text-sm" key={k}><span>{k}</span><b>{v}</b></div>)}</div></ChartCard><ChartCard title="Recent Leads"><LeadTable rows={data.recentLeads || []} compact /></ChartCard><ChartCard title="Top Source Performance"><div className="mt-4 space-y-3">{sourcePerformance.slice(0,6).map(source=><div key={source.label} className="grid grid-cols-[1fr_55px_75px] items-center gap-3 border-b pb-2 text-xs"><b>{source.label||'Unknown'}</b><span>{source.value} leads</span><div><div className="h-1.5 rounded bg-slate-100"><i className="block h-full rounded bg-emerald-500" style={{width:`${Math.min(100,source.rate)}%`}}/></div><span>{source.rate.toFixed(1)}%</span></div></div>)}{!sourcePerformance.length&&<Empty/>}</div></ChartCard></div>
  </Page>;
}

function Filters({ filters, setFilters, options, kind = 'lead' }) { return <div className={`${card} lead-filter-bar flex flex-wrap items-end gap-3 p-4`}><div className="relative min-w-[260px] flex-[1.6]"><Search className="absolute left-3 top-3 h-4 w-4 text-slate-400" /><input className={`${field} pl-9`} placeholder={kind==='lead'?'Search by Lead Name, Company, Contact...':`Search ${kind}s by name, email, phone...`} value={filters.search || ''} onChange={(e) => setFilters({ ...filters, search: e.target.value, page: 0 })} /></div>{kind === 'lead' && <><select className={field} value={filters.status || ''} onChange={(e) => setFilters({ ...filters, status: e.target.value, page: 0 })}><option value="">All Status</option>{['NEW','CONTACTED','QUALIFIED','PROPOSAL','NEGOTIATION','WON','LOST','CONVERTED'].map((x) => <option key={x}>{x.replaceAll('_',' ')}</option>)}</select><select className={field} value={filters.type || ''} onChange={(e) => setFilters({ ...filters, type: e.target.value, page: 0 })}><option value="">All Lead Types</option><option value="FIXED_COST">Fixed Cost</option><option value="STAFFING">Staffing</option></select><select className={field} value={filters.pipelineId || ''} onChange={(e) => setFilters({ ...filters, pipelineId: e.target.value, page: 0 })}><option value="">All Pipelines</option>{options?.pipelines?.map((p) => <option key={p.id} value={p.id}>{p.name}</option>)}</select><SkillSelect compact label="Primary Skill" value={filters.primarySkillId} onChange={(value)=>setFilters({...filters,primarySkillId:value,page:0})} items={options?.skills||[]}/><select className={field} value={filters.source||''} onChange={(e)=>setFilters({...filters,source:e.target.value,page:0})}><option value="">All Source</option>{options?.sources?.map(x=><option key={x}>{x}</option>)}</select><select className={field} value={filters.owner||''} onChange={(e)=>setFilters({...filters,owner:e.target.value,page:0})}><option value="">All Owners</option>{options?.owners?.map(x=><option key={x}>{x}</option>)}</select></>}<button className="ml-auto h-10 px-3 text-xs font-bold text-red-600" onClick={() => setFilters({ page: 0, size: 10 })}>Clear</button><button className={primary}>Apply</button></div>; }
function LeadTable({ rows, compact = false, onAssign, onDelete }) { return <div className="overflow-x-auto"><table className="w-full min-w-[900px] text-left text-sm"><thead className="bg-slate-50 text-xs text-slate-500"><tr>{['Lead Name','Company','Contact','Type','Pipeline','Status','Lead Score','Assignee','Created On','Actions'].map((x) => <th key={x} className="px-4 py-3">{x}</th>)}</tr></thead><tbody>{rows.map((r) => <tr key={r.id} className="border-t border-slate-100 hover:bg-slate-50"><td className="px-4 py-3 font-bold text-[#07152b]"><Link to={`/lead-management/leads/${r.id}`}>{r.leadName}</Link></td><td className="px-4 py-3">{r.companyName || '—'}</td><td className="px-4 py-3">{r.contactName || '—'}</td><td className="px-4 py-3"><Badge tone="violet">{r.leadType}</Badge></td><td className="px-4 py-3">{r.pipelineName}</td><td className="px-4 py-3"><Badge tone={tone(r.status)}>{r.stageName || r.status}</Badge></td><td className="px-4 py-3 font-bold text-emerald-600">{r.leadScore}</td><td className="px-4 py-3">{r.assignedUserName || r.ownerId || '—'}</td><td className="px-4 py-3">{date(r.createdAt)}</td><td className="px-4 py-3">{compact?<Link aria-label={`View ${r.leadName}`} to={`/lead-management/leads/${r.id}`}><Eye className="h-4 w-4"/></Link>:<RowMenu viewTo={`/lead-management/leads/${r.id}`} editTo={`/lead-management/leads/${r.id}/edit`} onAssign={()=>onAssign?.(r)} onDelete={()=>onDelete?.(r)}/>}</td></tr>)}</tbody></table>{!rows.length && <Empty />}</div>; }

export function LeadsPage() { const [filters,setFilters]=useState({page:0,size:10}); const [version,setVersion]=useState(0); const [deleting,setDeleting]=useState(null); const [assigning,setAssigning]=useState(null); const options=useLoad(leadApi.options,[]).data; const {data,loading,error}=useLoad(()=>leadApi.list(filters),[JSON.stringify(filters),version]); const exportQuery=new URLSearchParams(Object.entries(filters).filter(([key,value])=>!['page','size'].includes(key)&&value!==''&&value!=null)).toString(); const remove=async()=>{await leadApi.remove(deleting.id);setDeleting(null);setVersion(v=>v+1)}; const assigned=()=>{setAssigning(null);setVersion(v=>v+1)}; return <><Page title="Leads" subtitle="Manage and track all your leads in one place." actions={<><a className={btn} href={`/api/lead-export/leads${exportQuery?`?${exportQuery}`:''}`}><Download className="h-4 w-4" />Export</a><Link className={primary} to="/lead-management/leads/new"><Plus className="h-4 w-4" />New Lead</Link></>}><Stats items={[{label:'Total Leads',value:data?.totalElements,icon:Users},{label:'New Leads',value:data?.content?.filter(x=>x.status==='NEW').length,icon:UserRound},{label:'Qualified Leads',value:data?.content?.filter(x=>x.status==='QUALIFIED').length,icon:CheckCircle2},{label:'Converted Leads',value:data?.content?.filter(x=>x.status==='CONVERTED').length,icon:CircleDollarSign},{label:'Lost Leads',value:data?.content?.filter(x=>x.status==='LOST').length,icon:XCircle}]} /><Filters filters={filters} setFilters={setFilters} options={options} />{loading?<Loading error={error}/>:<div className={card}><LeadTable rows={data?.content||[]} onAssign={setAssigning} onDelete={setDeleting}/><Pager page={filters.page} totalPages={data?.totalPages} onChange={(page)=>setFilters({...filters,page})}/></div>}</Page>{assigning&&<AssignLeadModal lead={assigning} onClose={()=>setAssigning(null)} onSaved={assigned}/>}<ConfirmDialog open={Boolean(deleting)} title="Delete lead?" message={`Delete '${deleting?.leadName||'this lead'}'? This action cannot be undone.`} confirmLabel="Delete Lead" onCancel={()=>setDeleting(null)} onConfirm={remove}/></>; }

const defaultLead = { leadType:'FIXED_COST', source:'Website', priority:'MEDIUM', status:'NEW', leadScore:0, probability:10, primarySkillId:'', secondarySkill:'', typeDetails:{} };
export function LeadFormPage() { const {id}=useParams(); const nav=useNavigate(); const optionsState=useLoad(leadApi.options,[]); const existing=useLoad(()=>id?leadApi.get(id):Promise.resolve(defaultLead),[id]); const [form,setForm]=useState(null); const [errors,setErrors]=useState({}); useEffect(()=>{if(existing.data)setForm({...defaultLead,...existing.data,typeDetails:existing.data.typeDetails||{}})},[existing.data]); if(!form||optionsState.loading)return <Loading error={existing.error||optionsState.error}/>; const options=optionsState.data; const stages=options.stages.filter(s=>String(s.pipelineId)===String(form.pipelineId)); const set=(k,v)=>{setForm(f=>({...f,[k]:v}));setErrors(e=>({...e,[k]:''}))}; const submit=async(draft=false)=>{const secondarySkill=String(form.secondarySkill||'').trim();if(!draft&&!form.primarySkillId){setErrors({primarySkillId:'Please select a Primary Skill.'});return}if(secondarySkill.length>500){setErrors({secondarySkill:'Secondary Skill must not exceed 500 characters.'});return}try{const saved=await leadApi.save(id,{...form,secondarySkill},draft);nav(`/lead-management/leads/${saved.id}`)}catch(e){alert(e.response?.data?.message||e.message)}}; return <Page title={id?'Edit Lead':'Create Lead'} subtitle="Capture and qualify a potential business opportunity." actions={<><button className={btn} onClick={()=>nav(-1)}>Cancel</button><button className={btn} onClick={()=>submit(true)}>Save Draft</button><button className={primary} onClick={()=>submit(false)}>Save Lead</button></>}><div className="grid gap-4 xl:grid-cols-[1fr_360px]"><div className="space-y-4"><FormSection title="Lead Information"><FormGrid>{[['Lead Name','leadName','text'],['Expected Value','expectedValue','number'],['Expected Close Date','expectedCloseDate','date'],['Probability (%)','probability','number'],['Lead Score','leadScore','number'],['Next Step','nextStep','text']].map(([l,k,t])=><Field key={k} label={l} type={t} value={form[k]} onChange={v=>set(k,v)}/>)}<Select label="Lead Type" value={form.leadType} onChange={v=>set('leadType',v)} items={['FIXED_COST','STAFFING']}/><Select label="Pipeline" value={form.pipelineId} onChange={v=>{set('pipelineId',v);set('stageId','')}} items={options.pipelines} valueKey="id" labelKey="name"/><Select label="Stage" value={form.stageId} onChange={v=>{const s=stages.find(x=>String(x.id)===String(v));setForm(f=>({...f,stageId:v,status:s?.name?.toUpperCase().replaceAll(' ','_'),probability:s?.probability??f.probability}))}} items={stages} valueKey="id" labelKey="name"/><Select label="Source" value={form.source} onChange={v=>set('source',v)} items={options.sources}/><Select label="Owner" value={form.ownerId} onChange={v=>set('ownerId',v)} items={options.owners}/><SkillSelect label="Primary Skill" required value={form.primarySkillId} onChange={v=>set('primarySkillId',v)} items={options.skills||[]} error={errors.primarySkillId}/><Field label="Secondary Skill" value={form.secondarySkill} onChange={v=>set('secondarySkill',v)} placeholder="Enter secondary skills (e.g. Redis, Kafka, GraphQL)" maxLength={500} error={errors.secondarySkill}/><Select label="Priority" value={form.priority} onChange={v=>set('priority',v)} items={['LOW','MEDIUM','HIGH']}/></FormGrid><label className="block text-xs font-bold">Description<textarea className={`${field} mt-2 h-24 py-3`} value={form.description||''} onChange={e=>set('description',e.target.value)}/></label></FormSection><FormSection title="Company Information"><Select label="Link Existing Company" value={form.companyId} onChange={v=>set('companyId',v)} items={options.companies} valueKey="id" labelKey="companyName"/><Link className={btn} to="/lead-management/companies/new"><Plus className="h-4 w-4"/>New Company</Link></FormSection><FormSection title="Contact Information"><Select label="Primary Contact" value={form.primaryContactId} onChange={v=>set('primaryContactId',v)} items={options.contacts} valueKey="id" labelKey="contactName"/><Link className={btn} to="/lead-management/contacts/new"><Plus className="h-4 w-4"/>New Contact</Link></FormSection></div><div className="space-y-4"><FormSection title="Lead Type Specific Information">{(form.leadType==='STAFFING'?['numberOfResources','requiredExperience','engagementDuration','expectedStartDate','workLocation','workMode','budgetRange','requirements']:['projectDescription','scopeOfWork','budgetRange','timeline','clientLocation','requirements']).map(k=><Field key={k} label={k.replace(/([A-Z])/g,' $1').replace(/^./,c=>c.toUpperCase())} value={form.typeDetails?.[k]} onChange={v=>setForm(f=>({...f,typeDetails:{...f.typeDetails,[k]:v}}))}/>)}</FormSection><FormSection title="Additional Information"><Field label="Tags" value={form.tags} onChange={v=>set('tags',v)}/></FormSection></div></div></Page>; }
function FormSection({title,children}){return <section className={`${card} lead-form-section p-5`}><h2 className="mb-5 border-l-2 border-red-500 pl-3 text-[14px] font-extrabold text-[#07152b]">{title}</h2><div className="space-y-5">{children}</div></section>}
function FormGrid({children}){return <div className="grid gap-x-5 gap-y-5 md:grid-cols-2 xl:grid-cols-3">{children}</div>}
function Field({label,value,onChange,type='text',required,placeholder,maxLength,error}){return <label className="block text-[11px] font-bold text-[#25334a]">{label}{required&&<b className="text-red-500"> *</b>}<input className={`${field} mt-2 ${error?'border-red-500':''}`} type={type} value={value??''} maxLength={maxLength} placeholder={placeholder||`Enter ${String(label).toLowerCase()}`} onChange={e=>onChange(e.target.value)}/>{error&&<span className="mt-1 block text-[11px] font-semibold text-red-600">{error}</span>}</label>}
function Select({label,value,onChange,items=[],valueKey,labelKey}){
  if(label==='Link Existing Company'){
    return <EntitySearchSelect label={label} value={value} onChange={onChange} items={items} valueKey={valueKey||'id'} labelKey={labelKey||'companyName'} placeholder="Search and select company"/>;
  }
  return <label className="block min-w-40 text-[11px] font-bold text-[#25334a]">{label}<select className={`${field} mt-2`} value={value??''} onChange={e=>onChange(e.target.value)}><option value="">Select {label.toLowerCase()}</option>{items.map(x=><option key={valueKey?x[valueKey]:x} value={valueKey?x[valueKey]:x}>{labelKey?x[labelKey]:String(x).replaceAll('_',' ')}</option>)}</select></label>;
}
function SkillSelect({label,value,onChange,items=[],required=false,error,compact=false}){
  const root=useRef(null);
  const selected=items.find(item=>String(item.id)===String(value));
  const[query,setQuery]=useState(selected?.name||'');
  const[open,setOpen]=useState(false);
  useEffect(()=>{setQuery(items.find(item=>String(item.id)===String(value))?.name||'')},[value,items]);
  useEffect(()=>{const close=event=>{if(!root.current?.contains(event.target))setOpen(false)};document.addEventListener('mousedown',close);return()=>document.removeEventListener('mousedown',close)},[]);
  const visible=items.filter(item=>String(item.name||'').toLowerCase().includes(query.trim().toLowerCase()));
  const choose=item=>{setQuery(item.name);onChange(String(item.id));setOpen(false)};
  return <div ref={root} className={`${compact?'min-w-[180px]':'block'} relative text-[11px] font-bold text-[#25334a]`}>
    {!compact&&<label htmlFor={`${label.replace(/\W/g,'-')}-skill`}>{label}{required&&<b className="text-red-500"> *</b>}</label>}
    <div className={`${compact?'':'mt-2'} relative`}>
      <input id={`${label.replace(/\W/g,'-')}-skill`} role="combobox" aria-label={label} aria-expanded={open} aria-autocomplete="list" autoComplete="off" className={`${field} pr-9 ${error?'border-red-500':''}`} value={query} placeholder={compact?'All Primary Skills':'Search and select a skill'} onFocus={()=>setOpen(true)} onKeyDown={event=>{if(event.key==='Escape')setOpen(false);if(event.key==='ArrowDown')setOpen(true)}} onChange={event=>{setQuery(event.target.value);onChange('');setOpen(true)}}/>
      <button type="button" tabIndex={-1} aria-label={`Open ${label}`} className="absolute inset-y-0 right-0 grid w-9 place-items-center text-slate-500" onClick={()=>setOpen(current=>!current)}><ChevronDown className={`h-4 w-4 transition ${open?'rotate-180':''}`}/></button>
    </div>
    {open&&<div role="listbox" className="absolute left-0 right-0 z-[70] mt-1 max-h-56 overflow-y-auto rounded-md border border-slate-200 bg-white p-1 text-[13px] font-medium text-slate-800 shadow-xl">
      {compact&&<button type="button" className="block w-full rounded px-3 py-2 text-left hover:bg-slate-50" onMouseDown={event=>event.preventDefault()} onClick={()=>{setQuery('');onChange('');setOpen(false)}}>All Primary Skills</button>}
      {visible.map(item=><button type="button" role="option" aria-selected={String(item.id)===String(value)} key={item.id} className={`flex w-full items-center justify-between rounded px-3 py-2 text-left hover:bg-red-50 ${String(item.id)===String(value)?'bg-red-50 font-bold text-red-600':''}`} onMouseDown={event=>event.preventDefault()} onClick={()=>choose(item)}><span>{item.name}</span>{String(item.id)===String(value)&&<CheckCircle2 className="h-4 w-4"/>}</button>)}
      {!visible.length&&<p className="px-3 py-3 text-center text-xs text-slate-400">No skills found</p>}
    </div>}
    {error&&<span className="mt-1 block text-[11px] font-semibold text-red-600">{error}</span>}
  </div>
}

function EntitySearchSelect({label,value,onChange,items=[],valueKey='id',labelKey='name',placeholder='Search and select'}){
  const root=useRef(null);const selected=items.find(item=>String(item[valueKey])===String(value));
  const[query,setQuery]=useState(selected?.[labelKey]||'');const[open,setOpen]=useState(false);
  useEffect(()=>setQuery(items.find(item=>String(item[valueKey])===String(value))?.[labelKey]||''),[items,value,valueKey,labelKey]);
  useEffect(()=>{const close=event=>{if(!root.current?.contains(event.target))setOpen(false)};document.addEventListener('mousedown',close);return()=>document.removeEventListener('mousedown',close)},[]);
  const visible=items.filter(item=>String(item[labelKey]||'').toLowerCase().includes(query.trim().toLowerCase()));
  return <div ref={root} className="relative text-[11px] font-bold text-[#25334a]"><label>{label}</label><div className="relative mt-2"><input className={`${field} pr-9`} role="combobox" aria-expanded={open} value={query} placeholder={placeholder} autoComplete="off" onFocus={()=>setOpen(true)} onChange={event=>{setQuery(event.target.value);onChange('');setOpen(true)}}/><button type="button" tabIndex={-1} className="absolute inset-y-0 right-0 grid w-9 place-items-center text-slate-500" onClick={()=>setOpen(current=>!current)}><ChevronDown className="h-4 w-4"/></button></div>{open&&<div className="absolute left-0 right-0 z-[70] mt-1 max-h-56 overflow-y-auto rounded-md border border-slate-200 bg-white p-1 text-[13px] font-medium text-slate-800 shadow-xl">{visible.map(item=><button type="button" key={item[valueKey]} className={`flex w-full items-center justify-between rounded px-3 py-2 text-left hover:bg-red-50 ${String(item[valueKey])===String(value)?'bg-red-50 font-bold text-red-600':''}`} onMouseDown={event=>event.preventDefault()} onClick={()=>{setQuery(item[labelKey]);onChange(String(item[valueKey]));setOpen(false)}}><span>{item[labelKey]}</span>{String(item[valueKey])===String(value)&&<CheckCircle2 className="h-4 w-4"/>}</button>)}{!visible.length&&<p className="px-3 py-3 text-center text-xs text-slate-400">No companies found</p>}</div>}</div>
}

export function LeadDetailsPage(){const{id}=useParams();const nav=useNavigate();const{data:l,loading,error}=useLoad(()=>leadApi.get(id),[id]);const[tab,setTab]=useState('Overview');if(loading||!l)return <Loading error={error}/>;const add=async(type)=>{const content=prompt(`Enter ${type.slice(0,-1)} details`);if(!content)return;await supportApi.add(type,{entityType:'LEAD',entityId:id,...(type==='tasks'?{title:content}:type==='activities'?{title:content,activityType:'NOTE'}:{content})});location.reload()};return <Page title={l.leadName} subtitle={`${l.leadType} · ${l.pipelineName}`} actions={<><Link className={btn} to={`/lead-management/leads/${id}/edit`}><Edit3 className="h-4 w-4"/>Edit</Link><button className={primary} onClick={()=>{const stageId=prompt('Target stage ID');if(stageId)leadApi.convert(id,{stageId,amount:l.expectedValue,probability:l.probability,expectedCloseDate:l.expectedCloseDate}).then(()=>location.reload()).catch(e=>alert(e.response?.data?.message||e.message))}}>Convert</button><button className={btn} onClick={()=>nav(-1)}><ArrowLeft className="h-4 w-4"/>Back</button></>}><div className={`${card} p-5`}><div className="grid gap-4 sm:grid-cols-3 lg:grid-cols-6">{[['Owner',l.ownerId],['Status',l.stageName],['Expected Value',money(l.expectedValue)],['Probability',`${l.probability}%`],['Lead Score',l.leadScore],['Created',date(l.createdAt)]].map(([k,v])=><div key={k}><p className="text-xs text-slate-500">{k}</p><b className="text-sm">{v}</b></div>)}</div></div><div className="flex gap-6 overflow-auto border-b">{['Overview','Timeline','Activities','Notes','Attachments','Deals'].map(x=><button onClick={()=>setTab(x)} className={`pb-3 text-sm font-bold ${tab===x?'border-b-2 border-red-500 text-red-600':''}`} key={x}>{x}</button>)}</div>{tab==='Overview'?<div className="grid gap-4 xl:grid-cols-4"><Info title="Lead Information" values={{'Lead Name':l.leadName,Type:l.leadType,'Primary Skill':l.primarySkillName,'Secondary Skill':l.secondarySkill,Pipeline:l.pipelineName,Stage:l.stageName,Source:l.source,'Expected Close':date(l.expectedCloseDate),'Next Step':l.nextStep,Description:l.description}}/><Info title="Company" values={{Name:l.companyName,Email:l.companyEmail,Phone:l.companyPhone}}/><Info title="Primary Contact" values={{Name:l.contactName,Email:l.contactEmail,Phone:l.contactPhone}}/><Support title="Activities" rows={l.activities} action={()=>add('activities')}/><Support title="Contacts" rows={l.contacts} /><Support title="Notes" rows={l.notes} action={()=>add('notes')}/><Support title="Next Steps" rows={l.tasks} action={()=>add('tasks')}/><Support title="Related Deals" rows={l.deals}/></div>:<Support title={tab} rows={tab==='Timeline'?l.history:l[tab.toLowerCase()]||[]} action={['Activities','Notes'].includes(tab)?()=>add(tab.toLowerCase()):null}/>}</Page>}
function Info({title,values}){const fields=Object.entries(values).filter(([,value])=>value==null||['string','number','boolean'].includes(typeof value));return <section className={`${card} p-4`}><h3 className="mb-4 font-black">{title}</h3><div className="space-y-3">{fields.map(([key,value])=><div className="grid grid-cols-2 gap-3 text-xs" key={key}><span className="text-slate-500">{key}</span><b className="break-words">{value==null||value===''?'—':String(value)}</b></div>)}</div></section>}
function Support({title,rows=[],action}){if(title==='Contacts')return <section className={`${card} overflow-hidden`}><div className="flex items-center justify-between border-b border-slate-200 px-5 py-4"><h3 className="text-lg font-black">Contacts</h3><Link className="inline-flex h-10 items-center gap-2 rounded-full border border-emerald-500 px-5 text-sm font-bold text-emerald-600 hover:bg-emerald-50" to="/lead-management/contacts/new"><Plus className="h-4 w-4"/>Contact</Link></div><div className="overflow-x-auto"><table className="w-full min-w-[760px] text-left"><thead><tr><th className="px-5">Contact Name</th><th className="px-5">Email</th><th className="px-5">Mobile</th><th className="px-5">Title</th><th className="w-16 px-5">Actions</th></tr></thead><tbody>{rows.map((r,i)=><tr className="border-t border-slate-100" key={r.id||i}><td className="px-5 py-4"><Link className="font-bold hover:text-red-600" to={`/lead-management/contacts/${r.id}`}>{r.contactName||`${r.firstName||''} ${r.lastName||''}`.trim()||'Contact'}</Link></td><td className="px-5">{r.email||'—'}</td><td className="px-5">{r.phone||r.mobile||'—'}</td><td className="px-5">{r.jobTitle||r.designation||r.title||'—'}</td><td className="px-5"><MoreVertical className="h-4 w-4"/></td></tr>)}</tbody></table>{!rows.length&&<Empty/>}</div></section>;return <section className={`${card} p-4`}><div className="mb-4 flex items-center justify-between"><h3 className="font-black">{title}</h3>{action&&<button className="text-xs font-bold text-red-600" onClick={action}>+ Add</button>}</div><div className="space-y-3">{rows?.slice(0,6).map((r,i)=><div key={r.id||i} className="border-b pb-3 text-xs"><b>{r.title||r.content||r.contactName||r.dealName||r.toStage||r.file_name}</b><p className="mt-1 text-slate-500">{r.description||r.email||r.status||r.changedBy||date(r.created_at)}</p></div>)}{!rows?.length&&<Empty/>}</div></section>}

export function PipelineBoardPage(){const opts=useLoad(leadApi.options,[]);const[searchParams,setSearchParams]=useSearchParams();const[pipelineId,setPipelineId]=useState(()=>searchParams.get('pipelineId')||sessionStorage.getItem('leadPipelineId')||'');const[revision,setRevision]=useState(0);const[filters,setFilters]=useState({...currentFinancialYear(),owner:''});const[groupBy,setGroupBy]=useState('stage');useEffect(()=>{if(!opts.data?.pipelines?.length)return;const valid=opts.data.pipelines.some(p=>String(p.id)===String(pipelineId));if(!valid){const next=String(opts.data.pipelines[0].id);setPipelineId(next);sessionStorage.setItem('leadPipelineId',next);setSearchParams({pipelineId:next},{replace:true})}},[opts.data,pipelineId,setSearchParams]);const selectPipeline=value=>{setPipelineId(value);sessionStorage.setItem('leadPipelineId',value);setSearchParams({pipelineId:value},{replace:true})};const{data,loading,error}=useLoad(()=>pipelineId?pipelineApi.kanban(pipelineId):Promise.resolve(null),[pipelineId,revision]);const visibleStages=(data?.stages||[]).map(stage=>({...stage,leads:(stage.leads||[]).filter(lead=>(!filters.owner||String(lead.ownerId)===filters.owner)&&(!filters.from||String(lead.createdAt||'').slice(0,10)>=filters.from)&&(!filters.to||String(lead.createdAt||'').slice(0,10)<=filters.to))}));const drop=async(e,stageId)=>{const id=e.dataTransfer.getData('leadId');if(id){const stage=data.stages.find(s=>String(s.id)===String(stageId));if(['WON','LOST'].includes(stage.stageType)&&!confirm(`Move lead to ${stage.name}?`))return;const reason=stage.stageType==='LOST'?prompt('Lost reason'):undefined;await leadApi.stage(id,{stageId,reason});setRevision(value=>value+1)}};return <Page title="Pipeline" subtitle="Manage leads across your sales pipeline and track progress." actions={<><div className="flex items-center rounded-md border border-slate-200 bg-white px-2"><CalendarDays className="h-4 w-4"/><input aria-label="Pipeline from date" className="h-10 w-28 bg-transparent px-2 text-xs outline-none" type="date" value={filters.from} onChange={e=>setFilters({...filters,from:e.target.value})}/><span>–</span><input aria-label="Pipeline to date" className="h-10 w-28 bg-transparent px-2 text-xs outline-none" type="date" value={filters.to} onChange={e=>setFilters({...filters,to:e.target.value})}/></div><select aria-label="Pipeline filter" className={field} value={pipelineId} onChange={e=>selectPipeline(e.target.value)}>{opts.data?.pipelines?.map(p=><option key={p.id} value={p.id}>{p.name}</option>)}</select><select aria-label="Owner filter" className={field} value={filters.owner} onChange={e=>setFilters({...filters,owner:e.target.value})}><option value="">All Owners</option>{opts.data?.owners?.map(owner=><option key={owner}>{owner}</option>)}</select><button className={btn}><Filter className="h-4 w-4"/>Filters</button></>}>{loading||!data?<Loading error={error}/>:<><div className="flex justify-end"><Link className={primary} to="/lead-management/leads/new"><Plus className="h-4 w-4"/>New Lead</Link></div><Stats items={[{label:'Total Leads',value:visibleStages.reduce((sum,stage)=>sum+stage.leads.length,0),icon:Users},{label:'Pipeline Value',value:money(visibleStages.reduce((sum,stage)=>sum+stage.leads.reduce((value,lead)=>value+Number(lead.expectedValue||0),0),0)),icon:CircleDollarSign},{label:'Weighted Value',value:money(data.summary?.weightedValue),icon:BarChart3},{label:'Conversion Rate',value:`${Number(data.summary?.conversionRate||0).toFixed(2)}%`,icon:CheckCircle2},{label:'Average Lead Age',value:`${Math.round(data.summary?.averageAge||0)} Days`,icon:Clock3}]} /><div className="flex items-center justify-end gap-2 text-xs"><span>Group By:</span><select className={field} value={groupBy} onChange={e=>setGroupBy(e.target.value)}><option value="stage">Stage</option></select></div><div className="flex gap-3 overflow-x-auto pb-4">{visibleStages.map(stage=><div key={stage.id} onDragOver={e=>e.preventDefault()} onDrop={e=>drop(e,stage.id)} className={`${card} min-h-[540px] w-[290px] shrink-0 border-t-4 p-3`} style={{borderTopColor:stage.color}}><div className="mb-3 flex justify-between"><div><b>{stage.name} <span className="text-slate-400">({stage.leads.length})</span></b><p className="text-xs text-slate-500">{money(stage.leads.reduce((sum,lead)=>sum+Number(lead.expectedValue||0),0))}</p></div></div><div className="space-y-3">{stage.leads.map(l=><Link draggable onDragStart={e=>e.dataTransfer.setData('leadId',l.id)} to={`/lead-management/leads/${l.id}`} key={l.id} className="block rounded-lg border bg-white p-3 shadow-sm"><b className="text-sm">{l.leadName}</b><p className="mt-1 text-xs text-slate-500">{l.companyName||'No company'}</p><div className="mt-3 flex justify-between text-xs"><Badge>{l.source}</Badge><b>{money(l.expectedValue)}</b></div><div className="mt-3 flex justify-between text-[11px] text-slate-500"><span>{l.ownerId}</span><span>{date(l.createdAt)}</span></div></Link>)}</div><Link to={`/lead-management/leads/new?pipelineId=${pipelineId}&stageId=${stage.id}`} className="mt-4 flex h-9 items-center justify-center rounded-lg border text-xs font-bold"><Plus className="h-3 w-3"/> Add Lead</Link></div>)}</div></>}</Page>}

export function PipelinesPage(){
  const[f,setF]=useState({page:0,size:10});const[v,setV]=useState(0);const[deleting,setDeleting]=useState(null);
  const[deleteError,setDeleteError]=useState('');const[deleteBusy,setDeleteBusy]=useState(false);
  const{data,loading,error}=useLoad(()=>pipelineApi.list(f),[JSON.stringify(f),v]);
  const remove=async()=>{if(!deleting)return;setDeleteBusy(true);try{await pipelineApi.remove(deleting.id);setDeleting(null);setV(x=>x+1)}catch(e){setDeleting(null);setDeleteError(e.response?.data?.message||e.message||'The pipeline could not be deleted.')}finally{setDeleteBusy(false)}};
  return <><Page title="Lead Pipelines" subtitle="Manage your sales pipelines and track deal progress." actions={<><button className={btn}><Download className="h-4 w-4"/>Import</button><button className={btn}><Filter className="h-4 w-4"/>Filters</button><Link className={primary} to="/lead-management/pipelines/new"><Plus className="h-4 w-4"/>Create Pipeline</Link></>}><Stats items={[{label:'Total Pipelines',value:data?.totalElements},{label:'Total Leads',value:data?.content?.reduce((s,x)=>s+Number(x.leads||0),0)},{label:'Open Deals',value:data?.content?.reduce((s,x)=>s+Number(x.openDeals||0),0)},{label:'Won Deals',value:data?.content?.reduce((s,x)=>s+Number(x.wonDeals||0),0)},{label:'Lost Deals',value:data?.content?.reduce((s,x)=>s+Number(x.lostDeals||0),0)}]}/>{loading?<Loading error={error}/>:<div className={`${card} overflow-x-auto`}><table className="w-full min-w-[1000px] text-sm"><thead className="bg-slate-50 text-left text-xs"><tr>{['Pipeline Name','Description','Owner','Leads','Open Deals','Won Deals','Lost Deals','Win Rate','Status','Actions'].map(x=><th className="px-4 py-3" key={x}>{x}</th>)}</tr></thead><tbody>{data?.content?.map(p=><tr className="border-t" key={p.id}><td className="px-4 py-4 font-bold">{p.name}</td><td className="max-w-52 px-4">{p.description}</td><td className="px-4">{p.ownerId}</td><td className="px-4 text-blue-600">{p.leads}</td><td className="px-4 text-blue-600">{p.openDeals||0}</td><td className="px-4 text-emerald-600">{p.wonDeals||0}</td><td className="px-4 text-red-600">{p.lostDeals||0}</td><td className="px-4">{Number(p.wonDeals||0)+Number(p.lostDeals||0)?(Number(p.wonDeals||0)*100/(Number(p.wonDeals||0)+Number(p.lostDeals||0))).toFixed(1):0}%</td><td className="px-4"><Badge tone={p.active?'green':'slate'}>{p.active?'Active':'Inactive'}</Badge></td><td className="px-4"><RowMenu viewTo={`/lead-management/pipeline?pipelineId=${p.id}`} editTo={`/lead-management/pipelines/${p.id}/edit`} onDelete={()=>{setDeleteError('');setDeleting(p)}}/></td></tr>)}</tbody></table><Pager page={f.page} totalPages={data?.totalPages} onChange={page=>setF({...f,page})}/></div>}</Page><ConfirmDialog open={Boolean(deleting)} title="Delete pipeline?" message={`Delete '${deleting?.name||'this pipeline'}'? Pipelines containing leads cannot be deleted.`} confirmLabel="Delete Pipeline" loading={deleteBusy} onCancel={()=>!deleteBusy&&setDeleting(null)} onConfirm={remove}/><MessageDialog open={Boolean(deleteError)} title="Pipeline cannot be deleted" message={deleteError} onClose={()=>setDeleteError('')}/></>
}

const defaultStages=[['New Lead',10,'OPEN','#2563eb'],['Contacted',20,'OPEN','#3b82f6'],['Qualified',40,'OPEN','#10b981'],['Proposal',60,'OPEN','#f59e0b'],['Negotiation',80,'OPEN','#f97316'],['Won',100,'WON','#16a34a'],['Lost',0,'LOST','#ef1f2c']].map(([name,probability,stageType,color],i)=>({name,probability,stageType,color,expectedDurationDays:i+2}));
export function PipelineFormPage(){
  const{id}=useParams();const nav=useNavigate();
  const existing=useLoad(()=>id?pipelineApi.get(id):Promise.resolve({name:'',description:'',ownerId:'admin',currencyCode:'INR',pipelineType:'SALES',visibility:'ALL_USERS',expectedCloseDate:'',defaultProbability:10,color:'#ef1f2c',active:true,autoProbability:true,requireStageAge:false,requireLostReason:false,allowClosedEdit:true,allowDuplicateStages:false,stages:defaultStages}),[id]);
  const[f,setF]=useState(null);const[saving,setSaving]=useState(false);const[saveError,setSaveError]=useState('');useEffect(()=>existing.data&&setF(existing.data),[existing.data]);
  if(!f)return <Loading error={existing.error}/>;
  const set=(k,v)=>setF(x=>({...x,[k]:v}));
  const stageSet=(i,k,v)=>setF(x=>({...x,stages:x.stages.map((stage,index)=>index===i?{...stage,[k]:v}:stage)}));
  const addStage=()=>setF(x=>({...x,stages:[...x.stages,{name:'New Stage',probability:10,expectedDurationDays:3,color:'#2563eb',stageType:'OPEN'}]}));
  const removeStage=i=>setF(x=>({...x,stages:x.stages.filter((_,index)=>index!==i)}));
  const save=async()=>{setSaving(true);setSaveError('');try{await pipelineApi.save(id,f);nav('/lead-management/pipelines')}catch(e){setSaveError(e.response?.data?.message||e.message||'The pipeline could not be saved.')}finally{setSaving(false)}};
  const colors=['#ef1f2c','#2563eb','#22b394','#7458df','#f5b63f','#2698a8','#7c8798'];
  const total=f.stages.some(stage=>stage.stageType==='WON')?100:Math.max(0,...f.stages.map(stage=>Number(stage.probability||0)));
  const Toggle=({checked,onChange})=><button type="button" aria-pressed={checked} onClick={()=>onChange(!checked)} className={`relative h-6 w-11 rounded-full transition ${checked?'bg-red-600':'bg-slate-300'}`}><span className={`absolute top-1 h-4 w-4 rounded-full bg-white shadow transition ${checked?'left-6':'left-1'}`}/></button>;
  const Radio=({name,value,label,current,onChange})=><label className="flex cursor-pointer items-center gap-2 text-[13px] text-[#25334a]"><input className="h-4 w-4 accent-red-600" type="radio" name={name} value={value} checked={current===value} onChange={()=>onChange(value)}/>{label}</label>;
  return <><Page title={id?'Edit Pipeline':'Create Pipeline'} subtitle={`Set up a ${id?'':'new '}sales pipeline to track your leads and deals.`} actions={<><button className={btn} disabled={saving} onClick={()=>nav(-1)}>Cancel</button><button className={primary} disabled={saving} onClick={save}>{saving?'Saving…':'Save Pipeline'}</button></>}>
    <div className="grid items-start gap-5 xl:grid-cols-[minmax(0,1.7fr)_minmax(330px,1fr)]">
      <div className="space-y-5">
        <FormSection title="Pipeline Information">
          <div className="grid gap-x-8 gap-y-6 md:grid-cols-2 xl:grid-cols-[1fr_1.35fr]"><Field label="Pipeline Name" value={f.name} onChange={v=>set('name',v)} required/><label className="block text-[11px] font-bold text-[#25334a]">Description<textarea className={`${field} mt-2 h-[68px] resize-none py-3`} value={f.description||''} placeholder="Enter pipeline description" onChange={e=>set('description',e.target.value)}/></label></div>
          <div className="grid gap-5 md:grid-cols-3"><Select label="Pipeline Owner *" value={f.ownerId} onChange={v=>set('ownerId',v)} items={['admin','sales','accountant']}/><Select label="Default Currency *" value={f.currencyCode} onChange={v=>set('currencyCode',v)} items={['INR','USD','EUR']}/><Field label="Expected Close Date" type="date" value={f.expectedCloseDate} onChange={v=>set('expectedCloseDate',v)}/></div>
          <div className="grid gap-6 md:grid-cols-3"><div><p className="mb-3 text-[11px] font-bold text-[#25334a]">Pipeline Type</p><div className="flex gap-9"><Radio name="pipelineType" value="SALES" label="Sales" current={f.pipelineType} onChange={v=>set('pipelineType',v)}/><Radio name="pipelineType" value="CUSTOM" label="Custom" current={f.pipelineType} onChange={v=>set('pipelineType',v)}/></div></div><div><p className="mb-3 text-[11px] font-bold text-[#25334a]">Visible To <b className="text-red-500">*</b></p><div className="flex flex-wrap gap-7"><Radio name="visibility" value="ALL_USERS" label="All Users" current={f.visibility} onChange={v=>set('visibility',v)}/><Radio name="visibility" value="SELECTED_USERS" label="Select Users" current={f.visibility} onChange={v=>set('visibility',v)}/></div></div><div><p className="mb-2 text-[11px] font-bold text-[#25334a]">Active</p><Toggle checked={!!f.active} onChange={v=>set('active',v)}/></div></div>
        </FormSection>
        <section className={`${card} lead-form-section p-5`}><div className="mb-4 flex items-start justify-between gap-4"><div><h2 className="border-l-2 border-red-500 pl-3 text-[14px] font-extrabold text-[#07152b]">Pipeline Stages</h2><p className="mt-1 pl-3 text-xs text-slate-500">Add and arrange stages in your sales pipeline.</p></div><button className={btn} type="button" onClick={addStage}><Plus className="h-4 w-4"/>Add Stage</button></div>
          <div className="overflow-x-auto"><div className="min-w-[690px]"><div className="grid grid-cols-[36px_minmax(220px,1fr)_145px_180px_70px] bg-slate-50 px-2 py-3 text-center text-[11px] font-bold text-[#25334a]"><span/><span className="text-left">Stage Name</span><span>Probability (%)</span><span>Expected Duration (Days)</span><span>Actions</span></div>{f.stages.map((stage,i)=><div className="grid grid-cols-[36px_minmax(220px,1fr)_145px_180px_70px] items-center border-b border-slate-100 px-2 py-2" key={stage.id||i}><GripVertical className="h-4 w-4 cursor-grab text-slate-600"/><div className="relative"><i className="absolute left-3 top-1/2 h-3 w-3 -translate-y-1/2 rounded-full" style={{background:stage.color||f.color}}/><input className={`${field} pl-9`} value={stage.name||''} onChange={e=>stageSet(i,'name',e.target.value)}/></div><input aria-label={`${stage.name} probability`} className={`${field} mx-auto w-[105px]`} min="0" max="100" type="number" value={stage.probability??''} onChange={e=>stageSet(i,'probability',e.target.value)}/><input aria-label={`${stage.name} expected duration`} className={`${field} mx-auto w-[120px]`} min="0" type="number" value={stage.expectedDurationDays??''} onChange={e=>stageSet(i,'expectedDurationDays',e.target.value)}/><button aria-label={`Delete ${stage.name}`} className="mx-auto grid h-9 w-9 place-items-center rounded hover:bg-red-50" type="button" onClick={()=>removeStage(i)}><Trash2 className="h-4 w-4 text-red-500"/></button></div>)}</div></div>
          <div className="mt-4 flex items-center justify-between rounded-md border border-blue-100 bg-blue-50/50 px-4 py-3 text-xs text-slate-600"><span>ⓘ &nbsp; Total probability of all stages should be 100%.</span><b className={total===100?'text-emerald-600':'text-amber-600'}>Total: {total}%</b></div>
        </section>
      </div>
      <aside className="space-y-5">
        <FormSection title="Pipeline Settings"><label className="block text-[11px] font-bold text-[#25334a]">Default Probability <span title="Applied to new stages">ⓘ</span><div className="relative mt-2"><input className={`${field} pr-9`} min="0" max="100" type="number" value={f.defaultProbability??''} onChange={e=>set('defaultProbability',e.target.value)}/><span className="absolute right-3 top-2.5 text-sm">%</span></div></label><div><p className="mb-3 text-[11px] font-bold text-[#25334a]">Pipeline Color</p><div className="flex flex-wrap gap-3">{colors.map(color=><button key={color} type="button" aria-label={`Select ${color}`} onClick={()=>set('color',color)} className={`grid h-9 w-9 place-items-center rounded-md border-2 bg-white ${f.color===color?'border-red-500':'border-transparent'}`}><i className="grid h-7 w-7 place-items-center rounded text-sm font-bold text-white" style={{background:color}}>{f.color===color?'✓':''}</i></button>)}</div></div><div className="flex items-center justify-between"><span className="text-xs text-slate-600">Allow duplicate stages <span title="Allow stages with the same name">ⓘ</span></span><Toggle checked={!!f.allowDuplicateStages} onChange={v=>set('allowDuplicateStages',v)}/></div></FormSection>
        <FormSection title="Additional Settings">{[['autoProbability','Automatically update deal stage probability'],['requireStageAge','Require deal age for each stage'],['requireLostReason','Show lost reasons when moving to lost stage'],['allowClosedEdit','Allow editing of closed deals']].map(([k,label])=><label className="flex cursor-pointer items-center gap-3 text-xs text-slate-600" key={k}><input className="h-4 w-4 rounded accent-red-600" type="checkbox" checked={!!f[k]} onChange={e=>set(k,e.target.checked)}/>{label}</label>)}</FormSection>
        <section className="rounded-[10px] border border-blue-200 bg-blue-50/40 p-5"><h2 className="flex items-center gap-2 text-[14px] font-extrabold text-[#07152b]"><span className="text-blue-600">ⓘ</span> Pipeline Tips</h2><p className="mt-4 text-xs leading-6 text-slate-600">Create meaningful stages that reflect your sales process.<br/>You can reorder stages by dragging and dropping.</p></section>
      </aside>
    </div>
  </Page><MessageDialog open={Boolean(saveError)} title="Pipeline could not be saved" message={saveError} onClose={()=>setSaveError('')}/></>;
}

function EntityList({kind,api,title,subtitle,columns,stats}){const plural=kind==='company'?'companies':'contacts';const[f,setF]=useState({page:0,size:10});const[v,setV]=useState(0);const[deleting,setDeleting]=useState(null);const{data,loading,error}=useLoad(()=>api.list(f),[JSON.stringify(f),v]);const remove=()=>api.remove(deleting.id).then(()=>{setDeleting(null);setV(x=>x+1)}).catch(e=>alert(e.response?.data?.message||e.message));return <><Page title={title} subtitle={subtitle} actions={<><a href={`/api/lead-export/${plural}`} className={btn}><Download className="h-4 w-4"/>Export</a><button className={btn}><Filter className="h-4 w-4"/>Filters</button><Link className={primary} to={`/lead-management/${plural}/new`}><Plus className="h-4 w-4"/>Add {title.slice(0,-1)}</Link></>}><Stats items={stats(data)}/><Filters kind={kind} filters={f} setFilters={setF}/>{loading?<Loading error={error}/>:<div className={`${card} overflow-x-auto`}><table className="w-full min-w-[900px] text-left text-sm"><thead className="bg-slate-50 text-xs"><tr>{columns.map(c=><th className="px-4 py-3" key={c[0]}>{c[0]}</th>)}<th>Actions</th></tr></thead><tbody>{data?.content?.map(r=><tr className="border-t" key={r.id}>{columns.map(([label,key,render])=><td className="px-4 py-4" key={key}>{render?render(r[key],r):r[key]||'—'}</td>)}<td><RowMenu viewTo={`/lead-management/${plural}/${r.id}`} editTo={`/lead-management/${plural}/${r.id}/edit`} onDelete={()=>setDeleting(r)}/></td></tr>)}</tbody></table><Pager page={f.page} totalPages={data?.totalPages} onChange={page=>setF({...f,page})}/></div>}</Page><ConfirmDialog open={Boolean(deleting)} title={`Delete ${kind}?`} message={`Delete '${deleting?.companyName||deleting?.contactName||'this record'}'? This action cannot be undone.`} confirmLabel={`Delete ${kind}`} onCancel={()=>setDeleting(null)} onConfirm={remove}/></>}
const contactInitials = (record) => `${record.firstName?.[0] || ''}${record.lastName?.[0] || ''}`.toUpperCase() || 'C';
const contactAvatarTone = (id) => ['bg-red-50 text-red-600','bg-emerald-50 text-emerald-700','bg-violet-50 text-violet-700','bg-blue-50 text-blue-700'][Number(id || 0) % 4];
const contactTags = (value) => String(value || '').split(',').map((item) => item.trim()).filter(Boolean);

export function ContactsPage(){
  const [filters,setFilters]=useState({page:0,size:10});
  const [version,setVersion]=useState(0);
  const [deleting,setDeleting]=useState(null);
  const [view,setView]=useState('list');
  const [selected,setSelected]=useState([]);
  const [knownTags,setKnownTags]=useState([]);
  const options=useLoad(leadApi.options,[]).data;
  const {data,loading,error}=useLoad(()=>contactApi.list(filters),[JSON.stringify(filters),version]);
  const rows=data?.content||[];
  useEffect(()=>{const next=[...new Set(rows.flatMap((record)=>contactTags(record.tags)))];if(next.length)setKnownTags((current)=>[...new Set([...current,...next])]);},[data]);
  useEffect(()=>setSelected([]),[filters.page,filters.size]);
  const remove=async()=>{await contactApi.remove(deleting.id);setDeleting(null);setVersion(value=>value+1)};
  const reset=()=>setFilters({page:0,size:10});
  const update=(key,value)=>setFilters((current)=>({...current,[key]:value,page:0}));
  const active=rows.filter((record)=>record.status==='ACTIVE').length;
  const highPriority=rows.filter((record)=>contactTags(record.tags).some((tag)=>/high|hot|priority/i.test(tag))).length;
  const recent=rows.filter((record)=>record.createdAt&&Date.now()-new Date(record.createdAt).getTime()<=30*86400000).length;
  const total=Number(data?.totalElements||0);
  const first=total?filters.page*filters.size+1:0;
  const last=Math.min((filters.page+1)*filters.size,total);
  const pages=Math.max(Number(data?.totalPages||1),1);
  const pageNumbers=Array.from({length:Math.min(5,pages)},(_,index)=>Math.min(Math.max(0,filters.page-2),Math.max(0,pages-5))+index);
  const sourceTone=(value)=>String(value||'').toLowerCase().includes('referral')?'violet':'blue';
  return <>
    <Page title="Contacts" subtitle="Manage your contacts and build stronger relationships." actions={<><button className={btn}><Upload className="h-4 w-4"/>Import</button><a href="/api/lead-export/contacts" className={btn}><Download className="h-4 w-4"/>Export</a><button className={btn}><Filter className="h-4 w-4"/>Filters <ChevronDown className="h-4 w-4"/></button><Link className={primary} to="/lead-management/contacts/new"><Plus className="h-4 w-4"/>Add Contact</Link></>}>
      <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">
        {[{label:'Total Contacts',value:total,icon:Users,tone:'red',hint:'Across all contacts'},{label:'Active Contacts',value:active,icon:UserRound,tone:'green',hint:'In current result'},{label:'High Priority',value:highPriority,icon:Star,tone:'amber',hint:'Tagged high priority'},{label:'Recently Added',value:recent,icon:Clock3,tone:'violet',hint:'Added in last 30 days'}].map(({label,value,icon:Icon,tone:color,hint})=><section key={label} className={`${card} flex min-h-[108px] items-center gap-4 p-4`}><span className={`contact-stat-icon contact-stat-icon--${color} grid h-14 w-14 shrink-0 place-items-center rounded-full`}><Icon className="h-7 w-7"/></span><div><p className="text-[12px] font-bold text-slate-700">{label}</p><p className="mt-1 text-[25px] font-extrabold leading-none text-[#07152b]">{value}</p><p className="mt-2 text-[11px] text-slate-500">{hint}</p></div></section>)}
      </div>
      <section className="contact-filter-bar flex flex-wrap items-center gap-3 rounded-[10px] bg-white py-1">
        <div className="relative min-w-[300px] flex-[1.7]"><Search className="absolute left-3 top-3 h-4 w-4 text-slate-400"/><input className={`${field} pl-9`} value={filters.search||''} placeholder="Search contacts by name, email, phone, or company..." onChange={(event)=>update('search',event.target.value)}/></div>
        <select className={field} value={filters.type||''} onChange={(event)=>update('type',event.target.value)}><option value="">All Contacts</option><option value="PRIMARY">Primary</option><option value="OTHER">Other</option></select>
        <select className={field} value={filters.companyId||''} onChange={(event)=>update('companyId',event.target.value)}><option value="">All Companies</option>{options?.companies?.map((company)=><option key={company.id} value={company.id}>{company.companyName||company.name}</option>)}</select>
        <select className={field} value={filters.tag||''} onChange={(event)=>update('tag',event.target.value)}><option value="">All Tags</option>{knownTags.map((tag)=><option key={tag}>{tag}</option>)}</select>
        <select className={field} value={filters.owner||''} onChange={(event)=>update('owner',event.target.value)}><option value="">All Owners</option>{options?.owners?.map((owner)=><option key={owner}>{owner}</option>)}</select>
        <button className="inline-flex h-10 items-center gap-2 px-2 text-xs font-bold text-slate-600 hover:text-red-600" onClick={reset}><RotateCcw className="h-4 w-4"/>Reset</button>
        <div className="ml-auto flex gap-2"><button aria-label="List view" className={`grid h-10 w-10 place-items-center rounded-md border ${view==='list'?'border-red-400 text-red-600':'border-slate-200 text-slate-500'}`} onClick={()=>setView('list')}><List className="h-4 w-4"/></button><button aria-label="Grid view" className={`grid h-10 w-10 place-items-center rounded-md border ${view==='grid'?'border-red-400 text-red-600':'border-slate-200 text-slate-500'}`} onClick={()=>setView('grid')}><LayoutGrid className="h-4 w-4"/></button></div>
      </section>
      {loading?<Loading error={error}/>:view==='grid'?<div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-3">{rows.map((record)=><article className={`${card} p-5`} key={record.id}><div className="flex items-start gap-3"><span className={`grid h-11 w-11 place-items-center rounded-full text-sm font-extrabold ${contactAvatarTone(record.id)}`}>{contactInitials(record)}</span><div className="min-w-0 flex-1"><Link className="font-extrabold text-[#07152b] hover:text-red-600" to={`/lead-management/contacts/${record.id}`}>{record.contactName}</Link><p className="text-xs text-slate-500">{record.jobTitle||'Contact'}</p></div><RowMenu viewTo={`/lead-management/contacts/${record.id}`} editTo={`/lead-management/contacts/${record.id}/edit`} onDelete={()=>setDeleting(record)}/></div><div className="mt-5 space-y-2 text-xs text-slate-600"><p>{record.companyName||'No company linked'}</p><p>{record.email||'—'}</p><p>{record.phone||'—'}</p></div></article>)}{!rows.length&&<div className="col-span-full"><Empty/></div>}</div>:<section className={`${card} overflow-hidden`}><div className="overflow-x-auto"><table className="w-full min-w-[1120px] text-left"><thead><tr><th className="w-12 px-4"><input aria-label="Select all contacts" type="checkbox" checked={Boolean(rows.length)&&selected.length===rows.length} onChange={(event)=>setSelected(event.target.checked?rows.map((record)=>record.id):[])}/></th>{['Contact Name','Company','Email','Phone','Source','Owner','Tags','Created On','Actions'].map((label)=><th className="px-3" key={label}>{label}</th>)}</tr></thead><tbody>{rows.map((record)=><tr className="border-t border-slate-100" key={record.id}><td className="px-4"><input aria-label={`Select ${record.contactName}`} type="checkbox" checked={selected.includes(record.id)} onChange={(event)=>setSelected((current)=>event.target.checked?[...current,record.id]:current.filter((id)=>id!==record.id))}/></td><td className="px-3 py-3"><div className="flex items-center gap-3"><span className={`grid h-9 w-9 shrink-0 place-items-center rounded-full text-xs font-extrabold ${contactAvatarTone(record.id)}`}>{contactInitials(record)}</span><div><Link className="font-extrabold text-[#07152b] hover:text-red-600" to={`/lead-management/contacts/${record.id}`}>{record.contactName}</Link><p className="mt-0.5 text-[11px] text-slate-500">{record.jobTitle||'—'}</p></div></div></td><td className="px-3">{record.companyName||'—'}</td><td className="px-3">{record.email||'—'}</td><td className="px-3 whitespace-nowrap">{record.phone||'—'}</td><td className="px-3"><Badge tone={sourceTone(record.source)}>{record.source}</Badge></td><td className="px-3"><div className="flex items-center gap-2"><span className="grid h-7 w-7 place-items-center rounded-full bg-slate-100 text-[10px] font-extrabold">{String(record.ownerId||'—').slice(0,2).toUpperCase()}</span><span>{record.ownerId||'—'}</span></div></td><td className="px-3"><div className="flex flex-wrap gap-1">{contactTags(record.tags).slice(0,2).map((tag)=><Badge key={tag} tone={/hot|high/i.test(tag)?'red':'green'}>{tag}</Badge>)}{!contactTags(record.tags).length&&<span>—</span>}</div></td><td className="px-3 whitespace-nowrap">{date(record.createdAt)}</td><td className="px-3"><RowMenu viewTo={`/lead-management/contacts/${record.id}`} editTo={`/lead-management/contacts/${record.id}/edit`} onDelete={()=>setDeleting(record)}/></td></tr>)}</tbody></table>{!rows.length&&<Empty/>}</div><footer className="flex flex-wrap items-center justify-between gap-3 border-t border-slate-100 px-4 py-4 text-xs text-slate-500"><span>Showing {first} to {last} of {total} contacts</span><div className="flex items-center gap-2"><button className="grid h-9 w-9 place-items-center rounded-md border border-slate-200 disabled:opacity-40" disabled={!filters.page} onClick={()=>setFilters({...filters,page:filters.page-1})}>‹</button>{pageNumbers.map((page)=><button className={`grid h-9 min-w-9 place-items-center rounded-md border px-2 font-bold ${page===filters.page?'border-red-400 bg-red-50 text-red-600':'border-transparent text-slate-700'}`} key={page} onClick={()=>setFilters({...filters,page})}>{page+1}</button>)}<button className="grid h-9 w-9 place-items-center rounded-md border border-slate-200 disabled:opacity-40" disabled={filters.page+1>=pages} onClick={()=>setFilters({...filters,page:filters.page+1})}>›</button><select className="ml-3 h-9 rounded-md border border-slate-200 bg-white px-3" value={filters.size} onChange={(event)=>setFilters({...filters,size:Number(event.target.value),page:0})}>{[10,25,50].map((size)=><option key={size} value={size}>{size} / page</option>)}</select></div></footer></section>}
    </Page>
    <ConfirmDialog open={Boolean(deleting)} title="Delete contact?" message={`Delete '${deleting?.contactName||'this contact'}'? This action cannot be undone.`} confirmLabel="Delete Contact" onCancel={()=>setDeleting(null)} onConfirm={remove}/>
  </>;
}
const companyInitials=(name)=>String(name||'Company').split(/\s+/).slice(0,2).map(part=>part[0]).join('').toUpperCase();
export function CompaniesPage(){
  const financialYear=currentFinancialYear();
  const [filters,setFilters]=useState({page:0,size:10,...financialYear});
  const [draft,setDraft]=useState({search:'',status:'',industry:'',country:'',city:''});
  const [version,setVersion]=useState(0);
  const [deleting,setDeleting]=useState(null);
  const [selected,setSelected]=useState([]);
  const options=useLoad(leadApi.options,[]).data;
  const {data,loading,error}=useLoad(()=>companyApi.list(filters),[JSON.stringify(filters),version]);
  const rows=data?.content||[];
  useEffect(()=>setSelected([]),[filters.page,filters.size]);
  const total=Number(data?.totalElements||0);
  const active=rows.filter(record=>record.status==='ACTIVE').length;
  const inactive=rows.filter(record=>record.status==='INACTIVE').length;
  const recent=rows.filter(record=>record.createdAt&&Date.now()-new Date(record.createdAt).getTime()<=30*86400000).length;
  const industries=[...new Set(rows.map(record=>record.industry).filter(Boolean))];
  const countries=[...new Set(rows.map(record=>record.country).filter(Boolean))];
  const cities=[...new Set(rows.map(record=>record.city).filter(Boolean))];
  const apply=()=>setFilters(current=>({...current,...draft,page:0}));
  const clear=()=>{const empty={search:'',status:'',industry:'',country:'',city:''};setDraft(empty);setFilters(current=>({...current,...empty,page:0}));};
  const remove=async()=>{await companyApi.remove(deleting.id);setDeleting(null);setVersion(value=>value+1)};
  const first=total?filters.page*filters.size+1:0;
  const last=Math.min((filters.page+1)*filters.size,total);
  const pages=Math.max(Number(data?.totalPages||1),1);
  const pageNumbers=Array.from({length:Math.min(5,pages)},(_,index)=>Math.min(Math.max(0,filters.page-2),Math.max(0,pages-5))+index);
  return <>
    <Page title="Companies" subtitle="Manage all your companies and their related contacts." actions={<><div className="flex h-10 items-center gap-1 rounded-md border border-slate-200 bg-white px-2"><CalendarDays className="h-4 w-4 text-slate-500"/><input aria-label="Companies from date" className="w-[112px] bg-transparent text-[11px] outline-none" type="date" value={filters.from||''} onChange={event=>setFilters({...filters,from:event.target.value,page:0})}/><span className="text-slate-300">–</span><input aria-label="Companies to date" className="w-[112px] bg-transparent text-[11px] outline-none" type="date" value={filters.to||''} onChange={event=>setFilters({...filters,to:event.target.value,page:0})}/></div><select className={field} value={filters.owner||''} onChange={event=>setFilters({...filters,owner:event.target.value,page:0})}><option value="">All Owners</option>{options?.owners?.map(owner=><option key={owner}>{owner}</option>)}</select><button className={btn}><Filter className="h-4 w-4"/>Filters <ChevronDown className="h-4 w-4"/></button><button className={btn}>Customise</button></>}>
      <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">{[{label:'Total Companies',value:total,icon:Building2,tone:'blue',hint:'Across all companies'},{label:'Active Companies',value:active,icon:Building2,tone:'green',hint:'In current result'},{label:'New Companies',value:recent,icon:Plus,tone:'amber',hint:'Added in last 30 days'},{label:'Inactive Companies',value:inactive,icon:XCircle,tone:'red',hint:'In current result'}].map(({label,value,icon:Icon,tone:color,hint})=><section className={`${card} flex min-h-[108px] items-center gap-4 p-4`} key={label}><span className={`contact-stat-icon contact-stat-icon--${color} grid h-14 w-14 shrink-0 place-items-center rounded-full`}><Icon className="h-7 w-7"/></span><div><p className="text-[12px] font-bold text-slate-700">{label}</p><p className="mt-1 text-[25px] font-extrabold leading-none">{value}</p><p className="mt-2 text-[11px] text-slate-500">{hint}</p></div></section>)}</div>
      <section className={`${card} company-filter-bar flex flex-wrap items-center gap-3 p-3`}><div className="relative min-w-[275px] flex-[1.6]"><Search className="absolute left-3 top-3 h-4 w-4 text-slate-400"/><input className={`${field} pl-9`} placeholder="Search by Company Name, Email, Phone, Website..." value={draft.search} onChange={event=>setDraft({...draft,search:event.target.value})} onKeyDown={event=>event.key==='Enter'&&apply()}/></div><select className={field} value={draft.status} onChange={event=>setDraft({...draft,status:event.target.value})}><option value="">All Status</option><option value="ACTIVE">Active</option><option value="INACTIVE">Inactive</option></select><select className={field} value={draft.industry} onChange={event=>setDraft({...draft,industry:event.target.value})}><option value="">All Industry</option>{industries.map(value=><option key={value}>{value}</option>)}</select><select className={field} value={draft.country} onChange={event=>setDraft({...draft,country:event.target.value})}><option value="">All Country</option>{countries.map(value=><option key={value}>{value}</option>)}</select><select className={field} value={draft.city} onChange={event=>setDraft({...draft,city:event.target.value})}><option value="">All City</option>{cities.map(value=><option key={value}>{value}</option>)}</select><button className={btn}><Filter className="h-4 w-4"/>More Filters <ChevronDown className="h-4 w-4"/></button><button className="ml-auto h-10 px-2 text-xs font-bold text-red-600" onClick={clear}>Clear</button><button className={primary} onClick={apply}>Apply</button><div className="flex basis-full justify-end"><Link className={`${btn} border-red-400 text-red-600 hover:bg-red-50`} to="/lead-management/companies/new"><Plus className="h-4 w-4"/>Add Company</Link></div></section>
      {loading?<Loading error={error}/>:<section className={`${card} overflow-hidden`}><div className="overflow-x-auto"><table className="w-full min-w-[1120px] text-left"><thead><tr><th className="w-12 px-4"><input aria-label="Select all companies" type="checkbox" checked={Boolean(rows.length)&&selected.length===rows.length} onChange={event=>setSelected(event.target.checked?rows.map(record=>record.id):[])}/></th>{['Company Name','Industry','Phone','Email','Website','Contacts','Owner','Status','Created On','Actions'].map(label=><th className="px-3" key={label}>{label}</th>)}</tr></thead><tbody>{rows.map(record=><tr className="border-t border-slate-100" key={record.id}><td className="px-4"><input aria-label={`Select ${record.companyName}`} type="checkbox" checked={selected.includes(record.id)} onChange={event=>setSelected(current=>event.target.checked?[...current,record.id]:current.filter(id=>id!==record.id))}/></td><td className="px-3 py-3"><div className="flex items-center gap-3"><span className={`grid h-9 w-9 shrink-0 place-items-center rounded-full text-xs font-extrabold ${contactAvatarTone(record.id)}`}>{companyInitials(record.companyName)}</span><Link className="font-extrabold text-[#07152b] hover:text-red-600" to={`/lead-management/companies/${record.id}`}>{record.companyName}</Link></div></td><td className="px-3">{record.industry||'—'}</td><td className="px-3 whitespace-nowrap">{record.phone||'—'}</td><td className="px-3">{record.email||'—'}</td><td className="px-3">{record.website?<a className="text-blue-600 hover:underline" href={/^https?:/.test(record.website)?record.website:`https://${record.website}`} target="_blank" rel="noreferrer">{record.website}</a>:'—'}</td><td className="px-3 text-center"><Link className="font-bold text-blue-600" to={`/lead-management/companies/${record.id}`}>{record.contacts||0}</Link></td><td className="px-3"><div className="flex items-center gap-2"><span className="grid h-7 w-7 place-items-center rounded-full bg-slate-100 text-[10px] font-extrabold">{String(record.ownerId||'—').slice(0,2).toUpperCase()}</span>{record.ownerId||'—'}</div></td><td className="px-3"><Badge tone={tone(record.status)}>{record.status}</Badge></td><td className="px-3 whitespace-nowrap">{date(record.createdAt)}</td><td className="px-3"><RowMenu viewTo={`/lead-management/companies/${record.id}`} editTo={`/lead-management/companies/${record.id}/edit`} onDelete={()=>setDeleting(record)}/></td></tr>)}</tbody></table>{!rows.length&&<Empty/>}</div><footer className="flex flex-wrap items-center justify-between gap-3 border-t border-slate-100 px-4 py-4 text-xs text-slate-500"><span>Showing {first} to {last} of {total} companies</span><div className="flex items-center gap-2"><button className="grid h-9 w-9 place-items-center rounded-md border border-slate-200 disabled:opacity-40" disabled={!filters.page} onClick={()=>setFilters({...filters,page:filters.page-1})}>‹</button>{pageNumbers.map(page=><button className={`grid h-9 min-w-9 place-items-center rounded-md border px-2 font-bold ${page===filters.page?'border-red-400 bg-red-50 text-red-600':'border-transparent text-slate-700'}`} key={page} onClick={()=>setFilters({...filters,page})}>{page+1}</button>)}<button className="grid h-9 w-9 place-items-center rounded-md border border-slate-200 disabled:opacity-40" disabled={filters.page+1>=pages} onClick={()=>setFilters({...filters,page:filters.page+1})}>›</button><select className="ml-3 h-9 rounded-md border border-slate-200 bg-white px-3" value={filters.size} onChange={event=>setFilters({...filters,size:Number(event.target.value),page:0})}>{[10,25,50].map(size=><option key={size} value={size}>{size} / page</option>)}</select></div></footer></section>}
    </Page><ConfirmDialog open={Boolean(deleting)} title="Delete company?" message={`Delete '${deleting?.companyName||'this company'}'? This action cannot be undone.`} confirmLabel="Delete Company" onCancel={()=>setDeleting(null)} onConfirm={remove}/>
  </>;
}

const companyFields=['companyName','website','industry','companyType','email','phone','otherPhone','fax','gstin','pan','currencyCode','ownership','employeeRange','annualRevenue','leadSource','status','streetAddress','addressLine2','city','state','country','postalCode','linkedinUrl','facebookUrl','twitterUrl','tags'];
const contactFields=['firstName','lastName','jobTitle','email','phone','otherPhone','department','dateOfBirth','assistantName','ownerId','leadSource','contactType','companyId','tags','streetAddress','addressLine2','city','state','country','postalCode','skypeId','linkedinUrl','twitterUrl'];
export function EntityFormPage({kind}){const{id}=useParams();const nav=useNavigate();const api=kind==='company'?companyApi:contactApi;const existing=useLoad(()=>id?api.get(id):Promise.resolve(kind==='company'?{currencyCode:'INR',status:'ACTIVE',ownerId:'admin'}:{contactType:'PRIMARY',ownerId:'admin',status:'ACTIVE'}),[id,kind]);const opts=useLoad(leadApi.options,[]);const[f,setF]=useState(null);useEffect(()=>existing.data&&setF(existing.data),[existing.data]);if(!f)return <Loading error={existing.error}/>;const fields=kind==='company'?companyFields:contactFields;const save=()=>api.save(id,f).then(x=>nav(`/lead-management/${kind}s/${x.id}`)).catch(e=>alert(e.response?.data?.message||e.message));return <Page title={`${id?'Edit':'Create'} ${kind==='company'?'Company':'Contact'}`} subtitle={`Add ${kind} information and related details.`} actions={<><button className={btn} onClick={()=>nav(-1)}>Cancel</button><button className={primary} onClick={save}>Save {kind}</button></>}><div className="grid gap-4 xl:grid-cols-[1fr_360px]"><FormSection title={`${kind==='company'?'Company':'Contact'} Information`}><FormGrid>{fields.map(k=>k==='companyId'?<Select key={k} label="Company" value={f[k]} onChange={v=>setF({...f,[k]:v})} items={opts.data?.companies||[]} valueKey="id" labelKey="companyName"/>:<Field key={k} label={k.replace(/([A-Z])/g,' $1').replace(/^./,c=>c.toUpperCase())} type={k.includes('date')?'date':k==='annualRevenue'?'number':'text'} value={f[k]} onChange={v=>setF({...f,[k]:v})}/>)}</FormGrid><label className="block text-xs font-bold">Description<textarea className={`${field} mt-2 h-24 py-3`} value={f.description||''} onChange={e=>setF({...f,description:e.target.value})}/></label></FormSection><div className="space-y-4"><FormSection title="Notes"><textarea className={`${field} h-40 py-3`} value={f.notes||''} onChange={e=>setF({...f,notes:e.target.value})}/></FormSection><FormSection title="Attachments"><div className="grid h-36 place-items-center rounded-lg border border-dashed text-center text-sm text-slate-500"><Download className="h-6 w-6"/><span>Upload after saving the record</span></div></FormSection></div></div></Page>}

function CompanyDetailsView({data,id}){
  const [activeTab,setActiveTab]=useState('Overview');
  const contacts=data.contacts||[],deals=data.leads||[],activities=data.activities||[],tasks=data.tasks||[],notes=data.notesList||[];
  const openTasks=tasks.filter(item=>!['COMPLETED','CANCELLED'].includes(String(item.status||'').toUpperCase()));
  const openDeals=deals.filter(item=>!['WON','CONVERTED','LOST'].includes(String(item.status||item.stageName||'').toUpperCase()));
  const convertedDeals=deals.filter(item=>['WON','CONVERTED'].includes(String(item.status||item.stageName||'').toUpperCase()));
  const sum=rows=>rows.reduce((total,item)=>total+Number(item.expectedValue||item.amount||0),0);
  const initials=companyInitials(data.companyName);
  const address=[data.streetAddress,data.addressLine2,data.city,data.state,data.zipCode,data.country].filter(Boolean).join(', ');
  const ownerName=data.ownerName||data.owner?.name||data.createdByName||data.ownerId||'—';
  const created=data.createdAt||data.created_at;
  const latestActivity=activities[0];
  const tabs=[['Overview'],['Contacts',contacts.length],['Deals',deals.length],['Activities',activities.length],['Notes',notes.length],['Attachments',(data.attachments||[]).length],['Related Companies',(data.relatedCompanies||[]).length],['Emails',(data.emails||[]).length]];
  const rows=[['Company Name',data.companyName],['Industry',data.industry],['Type',data.companyType||data.type],['Website',data.website],['Phone',data.phone],['Email',data.email],['Address',address],['GSTIN',data.gstin],['PAN',data.pan],['Currency',data.currencyCode||data.currency],['Description',data.description]];
  const Panel=({title,children,action,className=''})=><section className={`${card} ${className}`}><div className="flex items-center justify-between border-b border-slate-100 px-4 py-3"><h3 className="text-sm font-black text-slate-900">{title}</h3>{action}</div>{children}</section>;
  const miniAction='inline-flex h-8 items-center gap-1 rounded-md border border-red-300 px-3 text-[11px] font-bold text-red-600 hover:bg-red-50';
  const renderOverview=()=> <div className="company-details-overview grid gap-4">
    <Panel title="Company Information" className="company-info-panel" action={<Link className="rounded-md border border-slate-200 p-1.5 text-slate-600" to={`/lead-management/companies/${id}/edit`}><Edit3 className="h-4 w-4"/></Link>}><div className="space-y-3 p-4">{rows.map(([label,value],index)=><div key={label} className={`${index===7?'border-t border-slate-100 pt-3':''} company-info-row grid grid-cols-2 gap-3 text-xs leading-5`}><span className="text-slate-500">{label}</span><b className={`${label==='Website'||label==='Email'?'text-blue-600':''} break-words font-semibold`}>{value||'—'}</b></div>)}</div></Panel>
    <Panel title={`Primary Contacts (${contacts.length})`} className="company-contacts-panel" action={<Link className={miniAction} to="/lead-management/contacts/new"><Plus className="h-3.5 w-3.5"/>Add Contact</Link>}><div className="flex min-h-[330px] flex-col p-4"><div className="space-y-5">{contacts.slice(0,5).map((contact,index)=><div className="flex items-start gap-3" key={contact.id||index}><span className={`flex h-10 w-10 shrink-0 items-center justify-center rounded-full text-xs font-black ${contactAvatarTone(index)}`}>{contactInitials(contact)}</span><div className="min-w-0 flex-1 text-xs"><div className="flex flex-wrap items-center gap-2"><b>{contact.contactName||`${contact.firstName||''} ${contact.lastName||''}`.trim()||'Contact'}</b>{(contact.primaryContact||contact.isPrimary||index===0)&&<span className="rounded bg-blue-50 px-2 py-0.5 text-[10px] font-bold text-blue-600">Primary Contact</span>}</div><p className="mt-1 text-slate-500">{contact.jobTitle||contact.designation||'—'}</p><p className="mt-1 break-all text-slate-600">{contact.email||'—'}</p>{contact.phone&&<p className="mt-1 text-slate-600">{contact.phone}</p>}</div><MoreVertical className="mt-1 h-4 w-4 text-slate-500"/></div>)}</div>{!contacts.length&&<Empty/>}{contacts.length>0&&<Link className="mt-auto pt-6 text-center text-xs font-bold text-red-600" to={`/lead-management/contacts?companyId=${id}`}>View All Contacts →</Link>}</div></Panel>
    <div className="company-summary-panel space-y-4"><Panel title="Company Summary"><div className="space-y-3 p-4 text-xs">{[['Total Deals',deals.length],['Open Deals Value',money(sum(openDeals))],['Converted Deals Value',money(sum(convertedDeals))],['Last Activity',latestActivity?date(latestActivity.occurredAt||latestActivity.createdAt||latestActivity.created_at):'—'],['Last Contacted By',latestActivity?.createdByName||latestActivity?.createdBy||'—'],['Lead Source',data.leadSource||'—'],['Lead Score',data.leadScore??'—'],['Status',<Badge tone="green">{data.status||'ACTIVE'}</Badge>]].map(([label,value])=><div className="flex items-center justify-between gap-3" key={label}><span className="text-slate-600">{label}</span><b className="text-right">{value}</b></div>)}</div></Panel><Panel title="Open Tasks" action={<Link className={miniAction} to={`/lead-management/leads?companyId=${id}`}><Plus className="h-3.5 w-3.5"/>Add Task</Link>}><div className="space-y-3 p-4">{openTasks.slice(0,3).map((item,index)=><div className="flex gap-3 text-xs" key={item.id||index}><span className="mt-1 h-3 w-3 rounded border border-slate-400"/><div className="flex-1"><b>{item.title||item.taskName}</b><p className="mt-1 text-slate-500">Due on {date(item.dueDate)}</p></div><Badge tone="amber">{item.priority||item.status}</Badge></div>)}{!openTasks.length&&<Empty/>}</div></Panel><Panel title={`Notes (${notes.length})`} action={<Link className={miniAction} to={`/lead-management/companies/${id}/edit`}><Plus className="h-3.5 w-3.5"/>Add Note</Link>}><div className="space-y-3 p-4">{notes.slice(0,3).map((item,index)=><div className="flex items-start gap-3 text-xs" key={item.id||index}><span className="flex h-7 w-7 items-center justify-center rounded-full bg-amber-50 text-amber-600">▣</span><div className="flex-1"><b>{item.title||item.content||'Note'}</b><p className="mt-1 text-slate-500">{date(item.createdAt||item.created_at)}{(item.createdByName||item.createdBy)&&` by ${item.createdByName||item.createdBy}`}</p></div><MoreVertical className="h-4 w-4"/></div>)}{!notes.length&&<Empty/>}</div></Panel></div>
    <Panel title="Recent Activities" className="company-activities-panel"><div className="divide-y divide-slate-100 px-4">{activities.slice(0,6).map((item,index)=><div className="grid gap-2 py-3 text-xs sm:grid-cols-4" key={item.id||index}><span className="text-slate-500">{date(item.occurredAt||item.createdAt||item.created_at)}</span><b>{item.title||item.activityType||item.type||'Activity'}</b><span className="text-slate-600">{item.description||'—'}</span><span className="text-right text-slate-500">by {item.createdByName||item.createdBy||'—'}</span></div>)}{!activities.length&&<Empty/>}</div></Panel>
  </div>;
  const tabRows={Contacts:contacts,Deals:deals,Activities:activities,Notes:notes,Attachments:data.attachments||[],'Related Companies':data.relatedCompanies||[],Emails:data.emails||[]};
  return <div className="lead-module space-y-4"><div className="text-xs text-slate-500"><Link to="/lead-management/companies">Companies</Link><span className="px-2">›</span><b className="text-slate-800">{data.companyName}</b></div><section className="border-b border-slate-200 bg-white pb-4"><div className="flex flex-wrap items-start justify-between gap-4"><div className="flex items-center gap-4"><span className="flex h-16 w-16 items-center justify-center rounded-xl bg-blue-50 text-2xl font-black text-blue-600">{initials}</span><div><div className="flex flex-wrap items-center gap-3"><h1 className="text-2xl font-black text-slate-900">{data.companyName}</h1><Badge tone="green">{data.status||'ACTIVE'}</Badge></div><div className="mt-3 flex flex-wrap gap-5 text-xs text-slate-600">{data.phone&&<span>☎ {data.phone}</span>}{data.email&&<a href={`mailto:${data.email}`}>✉ {data.email}</a>}{data.website&&<a href={data.website.startsWith('http')?data.website:`https://${data.website}`} target="_blank" rel="noreferrer">◎ {data.website}</a>}</div></div></div><div className="flex flex-wrap gap-2"><Link className={btn} to={`/lead-management/companies/${id}/edit`}><Edit3 className="h-4 w-4"/>Edit</Link><button className={btn}><MoreHorizontal className="h-4 w-4"/>More<ChevronDown className="h-4 w-4"/></button><button className={btn}>‹</button><button className={btn}>›</button></div></div><div className="mt-5 flex flex-wrap items-end justify-between gap-4"><div className="grid flex-1 gap-4 text-xs sm:grid-cols-3 lg:grid-cols-6">{[['Industry',data.industry],['Type',data.companyType||data.type],['Owner',ownerName],['Phone',data.phone],['Email',data.email],['Created On',date(created)]].map(([label,value])=><div className="border-r border-slate-200 pr-3" key={label}><p className="text-slate-500">{label}</p><b className="mt-2 block break-words">{value||'—'}</b></div>)}</div><div className="flex flex-wrap gap-2"><button className={`${btn} border-red-300 text-red-600`}>Create <ChevronDown className="h-4 w-4"/></button><a className={btn} href={`mailto:${data.email||''}`}><Mail className="h-4 w-4"/>Send Email</a><button className={btn}><CalendarDays className="h-4 w-4"/>Schedule Meeting</button><button className={btn}><MoreHorizontal className="h-4 w-4"/></button></div></div></section><nav className="flex overflow-x-auto border-b border-slate-200 bg-white">{tabs.map(([label,count])=><button className={`whitespace-nowrap border-b-2 px-5 py-3 text-xs font-bold ${activeTab===label?'border-red-500 text-red-600':'border-transparent text-slate-700 hover:text-red-600'}`} key={label} onClick={()=>setActiveTab(label)}>{label}{count!==undefined&&` (${count})`}</button>)}</nav>{activeTab==='Overview'?renderOverview():<Panel title={`${activeTab}${tabRows[activeTab]?.length?` (${tabRows[activeTab].length})`:''}`}><div className="p-4"><Support title={activeTab} rows={tabRows[activeTab]||[]}/></div></Panel>}</div>;
}

function ContactDetailsView({data,id}){const[activeTab,setActiveTab]=useState('Overview');const name=data.contactName||`${data.firstName||''} ${data.lastName||''}`.trim()||'Contact';const leads=data.leads||[],activities=data.activities||[],tasks=data.tasks||[],notes=data.notesList||[],attachments=data.attachments||[],emails=data.emails||[];const company=data.company||null;const companyName=data.companyName||company?.companyName||data.company?.name||'—';const address=[data.streetAddress,data.addressLine2,data.city,data.state,data.postalCode,data.country].filter(Boolean).join(', ');const owner=data.ownerName||data.ownerId||'—';const created=data.createdAt||data.created_at;const tabs=[['Overview'],['Related Leads',leads.length],['Activities',activities.length],['Tasks',tasks.length],['Notes',notes.length],['Attachments',attachments.length],['Emails',emails.length]];const Panel=({title,children,action,className=''})=><section className={`${card} ${className}`}><div className="flex items-center justify-between border-b border-slate-100 px-4 py-3"><h3 className="text-sm font-black">{title}</h3>{action}</div>{children}</section>;const fields=[['First Name',data.firstName],['Last Name',data.lastName],['Job Title',data.jobTitle],['Email',data.email],['Phone',data.phone],['Other Phone',data.otherPhone],['Department',data.department],['Contact Type',data.contactType],['Lead Source',data.leadSource],['Address',address],['LinkedIn',data.linkedinUrl],['Description',data.description]];const overview=<div className="company-details-overview grid gap-4"><Panel title="Contact Information" className="company-info-panel" action={<Link className="rounded-md border border-slate-200 p-1.5" to={`/lead-management/contacts/${id}/edit`}><Edit3 className="h-4 w-4"/></Link>}><div className="space-y-3 p-4">{fields.map(([label,value])=><div className="company-info-row grid grid-cols-2 gap-3 text-xs leading-5" key={label}><span className="text-slate-500">{label}</span><b className={`${label==='Email'||label==='LinkedIn'?'text-blue-600':''} break-words`}>{value||'—'}</b></div>)}</div></Panel><Panel title="Company" className="company-contacts-panel"><div className="min-h-[260px] p-5"><span className="grid h-12 w-12 place-items-center rounded-full bg-blue-50 text-sm font-black text-blue-600">{companyInitials(companyName)}</span><h3 className="mt-4 text-lg font-black">{companyName}</h3>{data.companyId&&<Link className="mt-2 inline-block text-xs font-bold text-blue-600" to={`/lead-management/companies/${data.companyId}`}>View Company</Link>}<div className="mt-5 space-y-3 text-xs text-slate-600"><p>◎ {company?.website||'—'}</p><p>✉ {company?.email||'—'}</p><p>☎ {company?.phone||'—'}</p></div></div></Panel><div className="company-summary-panel space-y-4"><Panel title="Contact Summary"><div className="space-y-3 p-4 text-xs">{[['Related Leads',leads.length],['Open Tasks',tasks.filter(x=>String(x.status).toUpperCase()!=='COMPLETED').length],['Activities',activities.length],['Lead Source',data.leadSource||'—'],['Owner',owner],['Status',<Badge tone="green">{data.status||'ACTIVE'}</Badge>]].map(([label,value])=><div className="flex justify-between gap-3" key={label}><span className="text-slate-500">{label}</span><b>{value}</b></div>)}</div></Panel><Support title="Open Tasks" rows={tasks}/><Support title="Notes" rows={notes}/></div><Panel title="Recent Activities" className="company-activities-panel"><div className="divide-y px-4">{activities.slice(0,6).map((item,index)=><div className="grid gap-2 py-3 text-xs sm:grid-cols-4" key={item.id||index}><span className="text-slate-500">{date(item.occurredAt||item.createdAt||item.created_at)}</span><b>{item.title||item.activityType||'Activity'}</b><span>{item.description||'—'}</span><span className="text-right text-slate-500">by {item.createdByName||item.createdBy||'—'}</span></div>)}{!activities.length&&<Empty/>}</div></Panel></div>;const tabRows={'Related Leads':leads,Activities:activities,Tasks:tasks,Notes:notes,Attachments:attachments,Emails:emails};return <div className="lead-module space-y-4"><div className="text-xs text-slate-500"><Link to="/lead-management/contacts">Contacts</Link><span className="px-2">›</span><b className="text-slate-800">{name}</b></div><section className="border-b border-slate-200 bg-white pb-4"><div className="flex flex-wrap items-start justify-between gap-4"><div className="flex items-center gap-4"><span className="grid h-16 w-16 place-items-center rounded-full bg-violet-50 text-xl font-black text-violet-600">{contactInitials(data)}</span><div><div className="flex flex-wrap items-center gap-3"><h1 className="text-2xl font-black">{name}</h1><Badge tone="green">{data.status||'ACTIVE'}</Badge></div><p className="mt-2 text-xs text-slate-500">{data.jobTitle||'—'} · {companyName}</p><div className="mt-3 flex flex-wrap gap-5 text-xs text-slate-600"><span>☎ {data.phone||'—'}</span><a href={`mailto:${data.email||''}`}>✉ {data.email||'—'}</a></div></div></div><div className="flex gap-2"><Link className={btn} to={`/lead-management/contacts/${id}/edit`}><Edit3 className="h-4 w-4"/>Edit</Link><button className={btn}><MoreHorizontal className="h-4 w-4"/>More</button></div></div><div className="mt-5 grid gap-4 text-xs sm:grid-cols-3 lg:grid-cols-6">{[['Company',companyName],['Owner',owner],['Department',data.department],['Type',data.contactType],['Source',data.leadSource],['Created On',date(created)]].map(([label,value])=><div className="border-r border-slate-200" key={label}><p className="text-slate-500">{label}</p><b className="mt-2 block">{value||'—'}</b></div>)}</div><div className="mt-4 flex justify-end gap-2"><a className={btn} href={`mailto:${data.email||''}`}><Mail className="h-4 w-4"/>Send Email</a><button className={btn}><CalendarDays className="h-4 w-4"/>Schedule Meeting</button></div></section><nav className="flex overflow-x-auto border-b border-slate-200 bg-white">{tabs.map(([label,count])=><button className={`whitespace-nowrap border-b-2 px-5 py-3 text-xs font-bold ${activeTab===label?'border-red-500 text-red-600':'border-transparent'}`} key={label} onClick={()=>setActiveTab(label)}>{label}{count!==undefined&&` (${count})`}</button>)}</nav>{activeTab==='Overview'?overview:<Support title={activeTab} rows={tabRows[activeTab]||[]}/>}</div>}

export function EntityDetailsPage({kind}){const{id}=useParams();const api=kind==='company'?companyApi:contactApi;const{data,loading,error}=useLoad(()=>api.get(id),[id]);if(loading||!data)return <Loading error={error}/>;if(kind==='company')return <CompanyDetailsView data={data} id={id}/>;return <ContactDetailsView data={data} id={id}/>}

export function LeadReportsPage(){const[filters,setFilters]=useState(currentFinancialYear);const options=useLoad(leadApi.options,[]).data;const{data,loading,error}=useLoad(()=>leadApi.dashboard(filters),[JSON.stringify(filters)]);if(loading||!data)return <Loading error={error}/>;return <Page title="Lead Reports" subtitle="Track, analyze and improve your lead performance." actions={<><a href={`/api/lead-export/leads?from=${filters.from}&to=${filters.to}`} className={btn}><Download className="h-4 w-4"/>Export</a><button className={btn}>Share</button><button className={btn}><MoreHorizontal className="h-4 w-4"/></button></>}><div className={`${card} grid gap-4 p-4 md:grid-cols-2 xl:grid-cols-[1.35fr_1fr_1fr_1fr_1fr_auto_auto]`}><label className="text-[11px] font-bold">Date Range<div className="mt-2 flex rounded-md border border-slate-200"><input aria-label="Report from date" className="h-10 min-w-0 flex-1 px-2 text-xs outline-none" type="date" value={filters.from} onChange={e=>setFilters({...filters,from:e.target.value})}/><input aria-label="Report to date" className="h-10 min-w-0 flex-1 px-2 text-xs outline-none" type="date" value={filters.to} onChange={e=>setFilters({...filters,to:e.target.value})}/></div></label><Select label="Lead Pipeline" value={filters.pipelineId||''} onChange={value=>setFilters({...filters,pipelineId:value})} items={options?.pipelines||[]} valueKey="id" labelKey="name"/><Select label="Lead Source" value={filters.source||''} onChange={value=>setFilters({...filters,source:value})} items={options?.sources||[]}/><Select label="Owner" value={filters.owner||''} onChange={value=>setFilters({...filters,owner:value})} items={options?.owners||[]}/><Select label="Lead Status" value={filters.status||''} onChange={value=>setFilters({...filters,status:value})} items={['NEW','CONTACTED','QUALIFIED','PROPOSAL','NEGOTIATION','WON','LOST','CONVERTED']}/><button className={`${btn} self-end`}><Filter className="h-4 w-4"/>Filters</button><button className="self-end pb-3 text-xs font-bold" onClick={()=>setFilters(currentFinancialYear())}>Reset</button></div><Stats items={[{label:'Total Leads',value:data.totalLeads,icon:Users},{label:'New Leads',value:data.newLeads,icon:UserRound},{label:'Converted Leads',value:data.convertedLeads,icon:CheckCircle2},{label:'Conversion Rate',value:`${data.conversionRate}%`,icon:BarChart3},{label:'Lost Leads',value:data.lostLeads,icon:XCircle}]}/><div className="grid gap-4 lg:grid-cols-3"><ChartCard title="Leads by Status"><Donut data={data.byStatus}/></ChartCard><ChartCard title="Leads by Source"><Bars data={data.bySource}/></ChartCard><ChartCard title="Leads Over Time"><Bars data={data.overTime}/></ChartCard></div><div className="grid gap-4 lg:grid-cols-2"><ChartCard title="Lead Performance Summary"><table className="mt-4 w-full text-sm"><thead><tr className="bg-slate-50 text-left text-xs"><th className="p-3">Owner</th><th>Total Leads</th><th>Converted</th><th>Conversion Rate</th></tr></thead><tbody>{data.byOwner?.map(x=><tr className="border-t" key={x.label}><td className="p-3 font-bold">{x.label}</td><td>{x.value}</td><td>{x.converted||0}</td><td>{x.value?(Number(x.converted||0)*100/Number(x.value)).toFixed(2):0}%</td></tr>)}</tbody></table></ChartCard><ChartCard title="Conversion Funnel"><div className="mx-auto mt-5 max-w-md space-y-1">{data.byStatus?.slice(0,6).map((x,i)=><div className="mx-auto flex h-10 items-center justify-center bg-red-500 text-sm font-bold text-white" style={{width:`${100-i*10}%`,opacity:1-i*.1}} key={x.label}>{x.label}: {x.value}</div>)}</div></ChartCard></div></Page>}
